/* ============================================================
   MADOUT 2 — Big City Life
   UI / HUD styles
   ============================================================ */
:root {
  --orange: #ff7a1a;
  --orange-hot: #ffb347;
  --pink: #ff2d6f;
  --cyan: #37e6ff;
  --ink: #070910;
  --panel: rgba(10, 13, 24, 0.62);
  --panel-line: rgba(255, 255, 255, 0.12);
  --text: #f4f1ea;
  --muted: rgba(244, 241, 234, 0.58);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --font-display: "Impact", "Haettenschweiler", "Arial Narrow Bold", "Franklin Gothic Heavy", sans-serif;
  --font-ui: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%; height: 100%;
  overflow: hidden;
  background: #070910;
  color: var(--text);
  font-family: var(--font-ui);
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}

body { position: fixed; inset: 0; }

#game { position: absolute; inset: 0; overflow: hidden; }

#scene {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}
#scene:active { cursor: grabbing; }

/* Cinematic grade + vignette */
#grade {
  position: absolute; inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 48%, rgba(0,0,0,0) 42%, rgba(3,5,12,0.42) 100%),
    linear-gradient(180deg, rgba(255,122,26,0.05), rgba(8,10,20,0) 28%, rgba(8,10,20,0) 72%, rgba(3,4,10,0.28));
  mix-blend-mode: normal;
  z-index: 2;
}
#grade::after {
  content: "";
  position: absolute; inset: 0;
  opacity: 0.055;
  background-image: repeating-linear-gradient(0deg, rgba(255,255,255,0.5) 0 1px, transparent 1px 3px);
  pointer-events: none;
}

#nitroTint {
  position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at 50% 55%, rgba(55,230,255,0) 38%, rgba(55,200,255,0.20) 100%);
  transition: opacity 0.18s linear;
}
#nitroTint.on { opacity: 1; }

#damageFlash {
  position: absolute; inset: 0; z-index: 4; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, rgba(255,30,30,0) 40%, rgba(255,25,25,0.55) 100%);
  transition: opacity 0.5s ease-out;
}
#damageFlash.hit { opacity: 1; transition: opacity 0.05s linear; }

.hidden { display: none !important; }

/* ============================================================
   HUD
   ============================================================ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }

#topLeft {
  position: absolute;
  top: calc(14px + var(--safe-t));
  left: calc(14px + var(--safe-l));
  display: flex; flex-direction: column; gap: 7px;
  width: 168px;
}
.brand-mini {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 22px;
  letter-spacing: 0.5px;
  line-height: 1;
  color: #fff;
  text-shadow: 0 2px 12px rgba(0,0,0,0.6);
}
.brand-mini span { color: var(--orange); margin-left: 2px; }

#wanted { display: flex; gap: 3px; height: 19px; align-items: center; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.6)); }
#wanted .star {
  width: 17px; height: 17px;
  background: rgba(255,255,255,0.16);
  clip-path: polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
  transition: background 0.2s, transform 0.2s;
}
#wanted .star.on { background: linear-gradient(180deg, #ffe259, #ffa751); transform: scale(1.06); }
#wanted .star.pulse { animation: starPop 0.45s ease-out; }
@keyframes starPop { 0% { transform: scale(1.9); } 100% { transform: scale(1.06); } }

.stat { display: flex; align-items: center; gap: 6px; }
.stat-ico { font-size: 11px; width: 27px; color: #ff8a8a; text-shadow: 0 1px 4px #000; }
.stat-ico.n2o { color: var(--cyan); font-weight: 800; font-size: 10px; letter-spacing: 0.4px; }
.bar {
  flex: 1; height: 7px; border-radius: 99px;
  background: rgba(0,0,0,0.5);
  border: 1px solid rgba(255,255,255,0.14);
  overflow: hidden;
  box-shadow: inset 0 1px 3px rgba(0,0,0,0.6);
}
.bar > i { display: block; height: 100%; width: 100%; border-radius: 99px; transition: width 0.15s linear; }
#healthBar { background: linear-gradient(90deg, #ff4d4d, #ff8a4d); }
#nitroBar { background: linear-gradient(90deg, #2fb8ff, #37e6ff); }
.bar.slim { height: 5px; }

#missionPanel {
  position: absolute;
  top: calc(14px + var(--safe-t));
  left: 50%;
  transform: translateX(-50%);
  width: clamp(190px, 27vw, 340px);
  padding: 10px 14px 11px;
  background: linear-gradient(180deg, rgba(11,14,26,0.78), rgba(11,14,26,0.45));
  border: 1px solid var(--panel-line);
  border-top: 2px solid var(--orange);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 10px 30px rgba(0,0,0,0.35);
}
#missionName {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 15px;
  letter-spacing: 1px;
  color: var(--orange-hot);
  line-height: 1.1;
}
#missionObjective { font-size: 12px; color: rgba(255,255,255,0.9); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mission-meta { display: flex; justify-content: space-between; font-size: 11px; color: var(--muted); margin: 6px 0 5px; font-variant-numeric: tabular-nums; }
#missionDist { color: #fff; font-weight: 700; }
#missionTimer { color: var(--orange-hot); font-weight: 700; }
#missionBar { background: linear-gradient(90deg, #ff7a1a, #ffd166); width: 100%; }
#missionPanel.urgent { animation: urgentPulse 0.8s infinite alternate; }
@keyframes urgentPulse { from { box-shadow: 0 0 0 rgba(255,60,60,0); } to { box-shadow: 0 0 26px rgba(255,60,60,0.55); } }

#topRight {
  position: absolute;
  top: calc(14px + var(--safe-t));
  right: calc(14px + var(--safe-r));
  display: flex; flex-direction: column; align-items: flex-end; gap: 8px;
}
#cashBox {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 26px;
  letter-spacing: 0.5px;
  color: #eaffd0;
  text-shadow: 0 2px 10px rgba(0,0,0,0.7), 0 0 18px rgba(120,255,120,0.15);
  display: flex; align-items: baseline; gap: 2px;
  font-variant-numeric: tabular-nums;
}
.cash-sign { color: #8dff7a; font-size: 0.8em; }
#cashBox.bump { animation: cashBump 0.3s ease-out; }
@keyframes cashBump { 50% { transform: scale(1.12); color: #fff; } }

#minimap {
  width: 168px; height: 168px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,0.28);
  box-shadow: 0 8px 26px rgba(0,0,0,0.5), inset 0 0 20px rgba(0,0,0,0.4);
  background: rgba(4,7,14,0.75);
}
#compass {
  width: 26px; height: 26px; margin-top: -3px;
  display: grid; place-items: center;
  color: var(--orange-hot);
  font-size: 15px;
  text-shadow: 0 0 10px rgba(255,160,60,0.8);
}

#speedo {
  position: absolute;
  bottom: calc(20px + var(--safe-b));
  left: 50%;
  transform: translateX(-50%);
  width: clamp(132px, 14vw, 184px);
  aspect-ratio: 1;
  z-index: 11;
  filter: drop-shadow(0 8px 24px rgba(0,0,0,0.5));
}
#speedo svg { width: 100%; height: 100%; transform: rotate(135deg); }
.gauge-track, .gauge-fill { fill: none; stroke-width: 9; stroke-linecap: round; }
.gauge-track { stroke: rgba(255,255,255,0.13); stroke-dasharray: 358 478; }
.gauge-fill {
  stroke: url(#speedGradient);
  stroke: var(--orange);
  stroke-dasharray: 358 478;
  stroke-dashoffset: 358;
  transition: stroke-dashoffset 0.08s linear, stroke 0.2s;
}
.speed-inner {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding-top: 4px;
}
#speedVal {
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(38px, 4.4vw, 56px);
  line-height: 0.9;
  color: #fff;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 3px 14px rgba(0,0,0,0.6);
}
.speed-unit { font-size: 9px; letter-spacing: 2.4px; color: var(--muted); margin-top: 3px; }
#gear {
  margin-top: 3px;
  font-size: 10px; font-weight: 800; letter-spacing: 1px;
  color: var(--orange-hot);
}

#modeHint {
  position: absolute;
  bottom: calc(30px + var(--safe-b));
  left: 50%; transform: translateX(-50%);
  padding: 6px 12px;
  font-size: 11px; letter-spacing: 1.4px;
  background: rgba(8,11,20,0.75);
  border: 1px solid var(--panel-line);
  border-radius: 99px;
  color: #fff;
}

#pauseBtn {
  position: absolute;
  top: calc(190px + var(--safe-t));
  right: calc(14px + var(--safe-r));
  width: 34px; height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.22);
  background: rgba(8,11,20,0.6);
  color: #fff;
  font-size: 10px; letter-spacing: 1px;
  pointer-events: auto;
  backdrop-filter: blur(6px);
  cursor: pointer;
  opacity: 0.75;
}
#pauseBtn:hover { opacity: 1; }

#keyHints {
  position: absolute;
  bottom: calc(18px + var(--safe-b));
  left: calc(16px + var(--safe-l));
  display: flex; gap: 14px;
  font-size: 10px; color: rgba(255,255,255,0.5);
  letter-spacing: 0.5px;
}
#keyHints b { color: rgba(255,255,255,0.82); font-weight: 700; }

/* ============================================================
   TOUCH CONTROLS
   ============================================================ */
#touch { position: absolute; inset: 0; z-index: 12; pointer-events: none; }

.tbtn {
  pointer-events: auto;
  -webkit-appearance: none;
  appearance: none;
  border: 1px solid rgba(255,255,255,0.24);
  background:
    radial-gradient(circle at 35% 25%, rgba(255,255,255,0.16), rgba(255,255,255,0.02) 60%),
    rgba(9,12,22,0.58);
  color: rgba(255,255,255,0.92);
  font-family: var(--font-ui);
  font-weight: 800;
  font-size: 20px;
  border-radius: 50%;
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  box-shadow: 0 8px 22px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.12);
  touch-action: none;
  transition: transform 0.06s linear, background 0.1s, border-color 0.1s;
  display: grid; place-items: center;
}
.tbtn.pressed, .tbtn:active {
  transform: scale(0.92);
  background:
    radial-gradient(circle at 35% 25%, rgba(255,190,90,0.5), rgba(255,122,26,0.18) 65%),
    rgba(24,16,8,0.7);
  border-color: rgba(255,160,70,0.8);
  color: #fff;
}

#steerPad {
  position: absolute;
  left: calc(16px + var(--safe-l));
  bottom: calc(20px + var(--safe-b));
  display: flex; gap: 10px;
}
#steerPad .steer { width: clamp(58px, 9vw, 76px); aspect-ratio: 1; font-size: 22px; }

#pedals {
  position: absolute;
  right: calc(16px + var(--safe-r));
  bottom: calc(20px + var(--safe-b));
  display: flex; flex-direction: column; gap: 9px; align-items: center;
}
#pedals .pedal { width: clamp(60px, 9vw, 78px); aspect-ratio: 1; }
#pedals .gas { border-color: rgba(120,255,140,0.4); color: #d8ffd8; }
#pedals .brake { width: clamp(50px, 7.4vw, 64px); color: #ffd6d6; border-color: rgba(255,120,120,0.35); }

#sideBtns {
  position: absolute;
  right: calc(16px + var(--safe-r) + clamp(70px, 10.5vw, 92px));
  bottom: calc(22px + var(--safe-b));
  display: flex; flex-direction: column; gap: 8px; align-items: center;
}
#sideBtns .small {
  width: clamp(46px, 6.6vw, 58px); aspect-ratio: 1;
  font-size: 9px; letter-spacing: 0.4px; line-height: 1.1;
}
#sideBtns .small sub { font-size: 7px; }
#sideBtns .accent {
  border-color: rgba(255,170,70,0.7);
  background: rgba(60,32,8,0.7);
  color: #ffd9a8;
  font-size: 8px;
}

/* ============================================================
   SCREENS
   ============================================================ */
.screen {
  position: absolute; inset: 0; z-index: 30;
  display: flex; align-items: center; justify-content: center;
  padding: calc(20px + var(--safe-t)) calc(20px + var(--safe-r)) calc(20px + var(--safe-b)) calc(20px + var(--safe-l));
  background:
    radial-gradient(ellipse at 50% 120%, rgba(255,90,20,0.20), rgba(5,7,14,0) 55%),
    radial-gradient(ellipse at 20% 10%, rgba(255,45,111,0.12), rgba(5,7,14,0) 45%),
    linear-gradient(180deg, rgba(5,7,14,0.72), rgba(5,7,14,0.92));
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  overflow-y: auto;
}
#start { background: linear-gradient(180deg, rgba(5,7,14,0.35) 0%, rgba(5,7,14,0.66) 55%, rgba(5,7,14,0.94) 100%); }

.start-glow {
  position: absolute; left: 50%; top: 16%;
  width: 70vmax; height: 70vmax;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(255,122,26,0.18), rgba(255,45,111,0.06) 45%, transparent 65%);
  pointer-events: none;
  animation: glowBreathe 7s ease-in-out infinite alternate;
}
@keyframes glowBreathe { from { opacity: 0.6; transform: translate(-50%,-50%) scale(0.95); } to { opacity: 1; transform: translate(-50%,-50%) scale(1.08); } }

.start-inner { position: relative; width: min(780px, 94vw); text-align: center; padding-bottom: 10px; }
.eyebrow { font-size: 10px; letter-spacing: 4px; color: var(--orange-hot); font-weight: 700; text-transform: uppercase; }
.logo {
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 900;
  font-size: clamp(76px, 17vw, 168px);
  line-height: 0.82;
  letter-spacing: -3px;
  margin: 6px 0 2px;
  background: linear-gradient(180deg, #ffffff 0%, #ffe9cf 32%, #ffb15c 58%, #ff6a00 100%);
  -webkit-background-clip: text; background-clip: text;
  color: transparent;
  filter: drop-shadow(0 8px 0 rgba(80,20,0,0.35)) drop-shadow(0 18px 50px rgba(255,90,10,0.35));
  transform: skewX(-4deg);
}
.logo-two {
  color: var(--pink);
  -webkit-text-fill-color: var(--pink);
  font-size: 0.62em;
  margin-left: 6px;
  vertical-align: 0.28em;
  text-shadow: 0 0 30px rgba(255,45,111,0.7);
}
.tagline { font-family: var(--font-display); font-style: italic; font-size: clamp(13px, 1.7vw, 19px); letter-spacing: 3px; color: rgba(255,255,255,0.88); margin-top: 6px; }
.blurb { max-width: 520px; margin: 14px auto 0; font-size: 13px; line-height: 1.65; color: var(--muted); }

.feature-row {
  display: flex; justify-content: center; gap: clamp(18px, 5vw, 54px);
  margin: 22px 0 20px;
}
.feature-row > div { display: flex; flex-direction: column; gap: 2px; }
.feature-row b { font-family: var(--font-display); font-style: italic; font-size: clamp(22px, 3vw, 32px); color: #fff; }
.feature-row span { font-size: 9px; letter-spacing: 2px; color: var(--muted); }

.cta {
  pointer-events: auto;
