collideCircle(x,z,radius) {
  let hit = null;
  for (const c of this.colliders) {
    const cx = clamp(x, c.minX, c.maxX), cz = clamp(z, c.minZ, c.maxZ);
    let dx = x-cx, dz=z-cz; let d2 = dx*dx+dz*dz;
    if (d2 < radius*radius) {
      let d = Math.sqrt(d2);
      let nx, nz, push;
      if (d > 0.0001) { nx=dx/d; nz=dz/d; push = radius-d; }
      else { // center inside box, push to nearest face
        const dl = x-c.minX, dr = c.maxX-x, dt = z-c.minZ, db = c.maxZ-z;
        const m = Math.min(dl,dr,dt,db);
        if (m===dl){nx=-1;nz=0;push=dl+radius} ... 
      }
      x += nx*push; z += nz*push;
      hit = {nx,nz,push,box:c};
    }
  }
  return hit;
}
