  groundPlane, boxAt, cylAt, clamp, TAU,
} from './util.js';

export const ROAD_COORDS = [-192, -128, -64, 0, 64, 128, 192];
export const ROAD_W = 16;
export const BLOCK = 64;
export const CITY_HALF = 192;
export const BLOCK_CENTERS = [-160, -96, -32, 32, 96, 160];
