import * as THREE from '../vendor/three.module.js';
import { clamp, damp, glowTexture, Rand } from './util.js';

/* Shared materials */
const glassMat = new THREE.MeshStandardMaterial({
  color: 0x0d1822, roughness: 0.08, metalness: 0.9, transparent: true, opacity: 0.92,
});
const darkMat = new THREE.MeshStandardMaterial({ color: 0x15171b, roughness: 0.75, metalness: 0.2 });
const chromeMat = new THREE.MeshStandardMaterial({ color: 0xb9c0c9, roughness: 0.22, metalness: 0.95 });
const headMat = new THREE.MeshBasicMaterial({ color: 0xfff3d0 });
const tailMat = new THREE.MeshBasicMaterial({ color: 0xff2a1a });
const redGlowMat = new THREE.MeshBasicMaterial({ color: 0xff2038 });
const blueGlowMat = new THREE.MeshBasicMaterial({ color: 0x2f7bff });
const flameMat = new THREE.MeshBasicMaterial({
  color: 0x5ee6ff, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
});
const underglowTex = glowTexture('rgba(255,140,40,0.85)', 'rgba(255,60,0,0)');

const paintCache = new Map();
function paintMat(color) {
  if (!paintCache.has(color)) {
    paintCache.set(color, new THREE.MeshStandardMaterial({
      color, roughness: 0.32, metalness: 0.62,
    }));
  }
  return paintCache.get(color);
}

const CAR_COLORS = [
  0xd93025, 0xf2c14e, 0x2f7de1, 0x2fbf71, 0xe8e6df, 0x1b1d22,
  0x8b5cf6, 0xff7a1a, 0x24b3c7, 0xb02a3a, 0x9aa3ad, 0x5c7a3a,
];

/* ------------------------------------------------------------------ */
/* Car mesh factory                                                   */
/* ------------------------------------------------------------------ */
export function buildCarMesh(opts = {}) {
  const kind = opts.kind || 'sedan';
  const color = opts.color ?? 0xd93025;
  const group = new THREE.Group();
  const wheels = [];
  const paint = paintMat(color);

  const dims = {
    sedan: { L: 4.4, W: 1.88, H: 1.24, cabinL: 2.1, cabinH: 0.52, cabinZ: -0.18, wheelR: 0.36 },
    sport: { L: 4.35, W: 1.98, H: 1.08, cabinL: 1.9, cabinH: 0.46, cabinZ: -0.28, wheelR: 0.38 },
    suv: { L: 4.9, W: 2.0, H: 1.5, cabinL: 2.5, cabinH: 0.62, cabinZ: -0.15, wheelR: 0.42 },
    van: { L: 5.2, W: 2.05, H: 1.9, cabinL: 3.4, cabinH: 0.95, cabinZ: -0.3, wheelR: 0.4 },
    police: { L: 4.7, W: 1.95, H: 1.3, cabinL: 2.3, cabinH: 0.52, cabinZ: -0.2, wheelR: 0.38 },
  }[kind];
  const { L, W, H, cabinL, cabinH, cabinZ, wheelR } = dims;

  const bodyY = 0.52;
  const bodyH = H * 0.48;

  // main body
  const paintEntries = [];
  paintEntries.push({ geo: new THREE.BoxGeometry(W, bodyH, L).translate(0, bodyY, 0) });
  // hood + trunk lips
  paintEntries.push({ geo: new THREE.BoxGeometry(W * 0.94, 0.16, L * 0.28).translate(0, bodyY + bodyH / 2 + 0.04, L * 0.33) });
  paintEntries.push({ geo: new THREE.BoxGeometry(W * 0.94, 0.14, L * 0.2).translate(0, bodyY + bodyH / 2 + 0.03, -L * 0.39) });
  // side skirts
  paintEntries.push({ geo: new THREE.BoxGeometry(W + 0.04, 0.14, L * 0.72).translate(0, 0.32, 0) });
  // roof
  paintEntries.push({ geo: new THREE.BoxGeometry(W * 0.78, 0.1, cabinL * 0.9).translate(0, bodyY + bodyH / 2 + cabinH + 0.03, cabinZ) });
  // bumpers
  paintEntries.push({ geo: new THREE.BoxGeometry(W * 0.98, 0.26, 0.24).translate(0, 0.46, L / 2 - 0.02) });
  paintEntries.push({ geo: new THREE.BoxGeometry(W * 0.98, 0.26, 0.24).translate(0, 0.46, -L / 2 + 0.02) });
  // mirrors
  paintEntries.push({ geo: new THREE.BoxGeometry(0.18, 0.1, 0.3).translate(W / 2 + 0.04, bodyY + 0.34, L * 0.16) });
  paintEntries.push({ geo: new THREE.BoxGeometry(0.18, 0.1, 0.3).translate(-W / 2 - 0.04, bodyY + 0.34, L * 0.16) });

  if (kind === 'sport') {
    // rear wing
    paintEntries.push({ geo: new THREE.BoxGeometry(W * 0.86, 0.08, 0.42).translate(0, 1.02, -L / 2 + 0.22) });
    paintEntries.push({ geo: new THREE.BoxGeometry(0.09, 0.32, 0.14).translate(W * 0.34, 0.86, -L / 2 + 0.22) });
    paintEntries.push({ geo: new THREE.BoxGeometry(0.09, 0.32, 0.14).translate(-W * 0.34, 0.86, -L / 2 + 0.22) });
  }

  const paintMesh = new THREE.Mesh(mergeLocal(paintEntries), paint);
  paintMesh.castShadow = true;
  paintMesh.receiveShadow = true;
  group.add(paintMesh);

  // glass cabin
  const cabin = new THREE.Mesh(new THREE.BoxGeometry(W * 0.82, cabinH, cabinL), glassMat);
  cabin.position.set(0, bodyY + bodyH / 2 + cabinH / 2, cabinZ);
  cabin.castShadow = true;
  group.add(cabin);

  // dark trim: grille, splitter, exhaust, wheel arches
  const darkEntries = [];
  darkEntries.push({ geo: new THREE.BoxGeometry(W * 0.55, 0.16, 0.1).translate(0, 0.56, L / 2 + 0.01) });
  darkEntries.push({ geo: new THREE.BoxGeometry(W * 0.9, 0.12, 0.16).translate(0, 0.3, L / 2 - 0.05) });
  darkEntries.push({ geo: new THREE.BoxGeometry(0.16, 0.16, 0.3).translate(W * 0.32, 0.34, -L / 2 - 0.02) });
  darkEntries.push({ geo: new THREE.BoxGeometry(0.16, 0.16, 0.3).translate(-W * 0.32, 0.34, -L / 2 - 0.02) });
  if (kind === 'police') {
    darkEntries.push({ geo: new THREE.BoxGeometry(W * 0.5, 0.32, L * 0.36).translate(0, 0.66, -L * 0.12) });
  }

  if (opts.detailed) {
    // detailed wheels (can spin)
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const wheel = new THREE.Group();
      const tire = new THREE.Mesh(new THREE.CylinderGeometry(wheelR, wheelR, 0.3, 14), darkMat);
      tire.rotation.z = Math.PI / 2;
      tire.castShadow = true;
      wheel.add(tire);
      const rim = new THREE.Mesh(new THREE.CylinderGeometry(wheelR * 0.58, wheelR * 0.58, 0.32, 10), chromeMat);
      rim.rotation.z = Math.PI / 2;
      wheel.add(rim);
      wheel.position.set(sx * (W / 2 - 0.08), wheelR, sz * (L * 0.31));
      group.add(wheel);
      wheels.push(wheel);
    }
  } else {
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      darkEntries.push({
        geo: new THREE.CylinderGeometry(wheelR, wheelR, 0.3, 12)
          .rotateZ(Math.PI / 2)
          .translate(sx * (W / 2 - 0.08), wheelR, sz * (L * 0.31)),
      });
    }
  }
  group.add(new THREE.Mesh(mergeLocal(darkEntries), darkMat));

  // lights
  const lightEntries = [];
  const tailEntries = [];
  const zf = L / 2 + 0.03;
  const zb = -L / 2 - 0.03;
  for (const sx of [-1, 1]) {
    lightEntries.push({ geo: new THREE.BoxGeometry(0.42, 0.14, 0.08).translate(sx * W * 0.3, 0.66, zf) });
    tailEntries.push({ geo: new THREE.BoxGeometry(0.42, 0.12, 0.08).translate(sx * W * 0.3, 0.66, zb) });
  }
  const headMesh = new THREE.Mesh(mergeLocal(lightEntries), headMat);
  group.add(headMesh);
  const tailMesh = new THREE.Mesh(mergeLocal(tailEntries), tailMat);
  group.add(tailMesh);

  // police light bar
  let lightbar = null;
  const policeMats = [];
  if (kind === 'police') {
    const barBase = new THREE.Mesh(new THREE.BoxGeometry(W * 0.55, 0.1, 0.28), darkMat);
    barBase.position.set(0, bodyY + bodyH / 2 + cabinH + 0.12, cabinZ);
    group.add(barBase);
    const red = new THREE.Mesh(new THREE.BoxGeometry(W * 0.24, 0.14, 0.24), redGlowMat.clone());
    red.position.set(-W * 0.14, bodyY + bodyH / 2 + cabinH + 0.2, cabinZ);
    const blue = new THREE.Mesh(new THREE.BoxGeometry(W * 0.24, 0.14, 0.24), blueGlowMat.clone());
    blue.position.set(W * 0.14, bodyY + bodyH / 2 + cabinH + 0.2, cabinZ);
    group.add(red, blue);
    lightbar = { red, blue };
    policeMats.push(red.material, blue.material);
  }

  // nitro flames (player only)
  let flames = null;
  if (opts.detailed) {
    flames = new THREE.Group();
    for (const sx of [-1, 1]) {
      const flame = new THREE.Mesh(new THREE.ConeGeometry(0.17, 1.1, 7), flameMat);
      flame.geometry.rotateX(-Math.PI / 2);
      flame.position.set(sx * W * 0.26, 0.36, -L / 2 - 0.5);
      flame.visible = false;
      flames.add(flame);
    }
    group.add(flames);
  }

  // underglow
  let underglow = null;
  if (opts.detailed) {
    const g = new THREE.PlaneGeometry(W * 1.7, L * 1.25);
    g.rotateX(-Math.PI / 2);
    underglow = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
      map: underglowTex, transparent: true, opacity: 0.5,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
    underglow.position.y = 0.07;
    group.add(underglow);
  }

  // headlight beam
  let beam = null;
  if (opts.detailed) {
    beam = new THREE.SpotLight(0xffe6b0, 22, 55, 0.52, 0.45, 1.4);
    beam.position.set(0, 0.8, L / 2);
    beam.target.position.set(0, 0.2, L / 2 + 30);
    group.add(beam, beam.target);
  }

  return { group, wheels, lightbar, flames, underglow, beam, tailMesh, headMesh, dims, kind };
}

function mergeLocal(entries) {
  // tiny local merge (same implementation as util, avoids circular import concerns)
  const prepared = entries.map((e) => {
    const g = e.geo.index ? e.geo.toNonIndexed() : e.geo;
    return g;
  });
  let total = 0;
  for (const g of prepared) total += g.attributes.position.count;
  const pos = new Float32Array(total * 3), norm = new Float32Array(total * 3), uv = new Float32Array(total * 2);
  let o = 0;
  for (const g of prepared) {
    pos.set(g.attributes.position.array, o * 3);
    norm.set(g.attributes.normal.array, o * 3);
    if (g.attributes.uv) uv.set(g.attributes.uv.array, o * 2);
    o += g.attributes.position.count;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(norm, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  geo.computeBoundingSphere();
  return geo;
}

/* ------------------------------------------------------------------ */
/* Player vehicle physics                                             */
/* ------------------------------------------------------------------ */
export class Vehicle {
  constructor(scene, opts = {}) {
    this.scene = scene;
    this.kind = opts.kind || 'sport';
    this.color = opts.color ?? 0xff5a1f;
    this.maxSpeed = opts.maxSpeed || (this.kind === 'sport' ? 54 : 46);
    this.accel = opts.accel || (this.kind === 'sport' ? 17 : 13);
    this.radius = 1.55;
    this.pos = new THREE.Vector3();
    this.vel = new THREE.Vector3();
    this.heading = 0;
    this.speed = 0;
    this.lateral = 0;
    this.nitro = 100;
    this.boosting = false;
    this.lastImpact = 0;
    this.collision = null;
    this.wheelSpin = 0;
    this.surface = 'road';
    this.mesh = null;
    this._build();
  }

  _build() {
    if (this.mesh) {
      this.scene.remove(this.mesh.group);
    }
    const built = buildCarMesh({
      kind: this.kind, color: this.color, detailed: true,
    });
    this.mesh = built;
    this.scene.add(built.group);
    this.mesh.group.position.copy(this.pos);
    this.mesh.group.rotation.y = this.heading;
  }

  setLook(kind, color) {
    this.kind = kind;
    this.color = color;
    const keepPos = this.pos.clone();
    const keepHeading = this.heading;
    const keepVel = this.vel.clone();
    this._build();
    this.pos.copy(keepPos);
    this.heading = keepHeading;
    this.vel.copy(keepVel);
    this.maxSpeed = kind === 'sport' ? 54 : kind === 'van' ? 42 : kind === 'suv' ? 45 : 48;
    this.accel = kind === 'sport' ? 17 : kind === 'van' ? 11 : 14;
  }

  reset(x, z, heading = 0) {
    this.pos.set(x, 0, z);
    this.vel.set(0, 0, 0);
    this.heading = heading;
    this.speed = 0;
    this.lateral = 0;
    this.nitro = 100;
    this.collision = null;
    this.lastImpact = 0;
    this._syncMesh(0);
  }

  update(dt, input, world, time) {
    const throttle = input.throttle || 0;
    const steer = input.steer || 0;
    const handbrake = !!input.handbrake;
    this.surface = world.surfaceAt(this.pos.x, this.pos.z);
    const offRoad = this.surface !== 'road';
    const sand = this.surface === 'sand';

    let fwd = new THREE.Vector3(Math.sin(this.heading), 0, Math.cos(this.heading));
    let right = new THREE.Vector3(Math.cos(this.heading), 0, -Math.sin(this.heading));
    let vF = this.vel.dot(fwd);
    let vR = this.vel.dot(right);

    const maxSpeed = (this.maxSpeed + (this.boosting ? 17 : 0)) * (sand ? 0.5 : offRoad ? 0.82 : 1);
    const accel = this.accel * (sand ? 0.55 : offRoad ? 0.8 : 1);

    // nitro
    const wantBoost = !!input.nitro && throttle > 0.2;
    if (wantBoost && this.nitro > 0.5) {
      this.boosting = true;
      this.nitro = Math.max(0, this.nitro - 30 * dt);
    } else {
      this.boosting = false;
      this.nitro = Math.min(100, this.nitro + (throttle > 0 ? 5.5 : 9) * dt);
    }

    // engine / brakes
    if (throttle > 0.01) {
      if (vF < -0.5) {
        vF = Math.min(0, vF + 30 * dt * throttle);
      } else {
        const headroom = clamp(1 - vF / maxSpeed, 0, 1);
        vF += accel * (0.35 + headroom * 0.9) * throttle * dt * (this.boosting ? 1.7 : 1);
      }
    } else if (throttle < -0.01) {
      if (vF > 0.5) {
        vF = Math.max(0, vF - 32 * dt * -throttle);
      } else {
        vF = Math.max(-13, vF - 8 * dt * -throttle);
      }
    } else {
      vF -= Math.sign(vF) * Math.min(Math.abs(vF), 2.6 * dt);
    }

    // drag
    vF *= Math.exp(-(offRoad ? 0.22 : 0.08) * dt);
    vF = clamp(vF, -14, maxSpeed);

    // handbrake
    if (handbrake) vF *= Math.exp(-0.9 * dt);

    // steering
    const speedRatio = clamp(Math.abs(vF) / 5, 0, 1);
    const highSpeedDamp = 1 - clamp(Math.abs(vF) / this.maxSpeed, 0, 1) * 0.4;
    const dir = vF >= 0 ? 1 : -1;
    const steerRate = (this.kind === 'van' ? 1.5 : 2.05) * highSpeedDamp;
    this.heading += steer * steerRate * speedRatio * dir * dt;

    // lateral grip (low grip while drifting / on sand)
    let grip = handbrake ? 1.5 : this.surface === 'sand' ? 3.5 : offRoad ? 6 : 9.2;
    if (this.boosting) grip *= 0.85;
    vR *= Math.exp(-grip * dt);

    // recompute basis after heading change
    fwd = new THREE.Vector3(Math.sin(this.heading), 0, Math.cos(this.heading));
    right = new THREE.Vector3(Math.cos(this.heading), 0, -Math.sin(this.heading));
    this.vel.copy(fwd).multiplyScalar(vF).addScaledVector(right, vR);

    this.pos.addScaledVector(this.vel, dt);

    // world collision
    this.collision = null;
    const hit = world.resolveCircle(this.pos, this.radius);
    if (hit) {
      const vn = this.vel.x * hit.nx + this.vel.z * hit.nz;
      const impact = Math.max(0, -vn);
      if (vn < 0) {
        this.vel.x -= (1 + 0.25) * vn * hit.nx;
        this.vel.z -= (1 + 0.25) * vn * hit.nz;
      }
      if (impact > 1.2) {
        this.collision = { impact, nx: hit.nx, nz: hit.nz };
        this.lastImpact = impact;
      }
      vF = this.vel.dot(fwd);
      vR = this.vel.dot(right);
    }

    this.speed = vF;
    this.lateral = vR;
    this._syncMesh(dt, steer, throttle, time);
  }

  _syncMesh(dt, steer = 0, throttle = 0, time = 0) {
    const g = this.mesh.group;
    const targetY = this.surface === 'sand' ? -0.28 : this.surface === 'road' ? 0 : 0.14;
    g.position.x = this.pos.x;
    g.position.z = this.pos.z;
    g.position.y = damp(g.position.y, targetY, 14, Math.max(dt, 0.016));
    g.rotation.y = this.heading;
    const speedRatio = clamp(Math.abs(this.speed) / this.maxSpeed, 0, 1);
    const drift = clamp(Math.abs(this.lateral) / 10, 0, 1);
    g.rotation.z = damp(g.rotation.z, -steer * speedRatio * 0.055 - this.lateral * 0.004, 8, dt || 0.016);
    g.rotation.x = damp(g.rotation.x, (throttle > 0 ? -0.008 : throttle < 0 ? 0.012 : 0) * speedRatio, 6, dt || 0.016);

    if (this.mesh.wheels.length) {
      this.wheelSpin += this.speed * (dt || 0) / 0.38;
      for (const w of this.mesh.wheels) w.rotation.x = this.wheelSpin;
    }
    if (this.mesh.flames) {
      const on = this.boosting && Math.abs(this.speed) > 4;
      for (const f of this.mesh.flames.children) {
        f.visible = on;
        if (on) {
          f.scale.z = 0.8 + Math.random() * 0.9;
          f.scale.x = f.scale.y = 0.8 + Math.random() * 0.4;
        }
      }
      if (this.mesh.underglow) this.mesh.underglow.material.opacity = on ? 0.8 : 0.4;
    }
    if (this.mesh.beam) this.mesh.beam.intensity = 12 + Math.sin(time * 40) * 0.4;
  }

  forward() {
    return new THREE.Vector3(Math.sin(this.heading), 0, Math.cos(this.heading));
  }

  get kmh() { return Math.abs(this.speed) * 3.6; }
  get driftFactor() { return clamp((Math.abs(this.lateral) - 1.4) / 8, 0, 1); }
}

/* ------------------------------------------------------------------ */
/* On-foot character                                                  */
/* ------------------------------------------------------------------ */
export function buildCharacter() {
  const group = new THREE.Group();
  const skin = new THREE.MeshStandardMaterial({ color: 0x8a5a3b, roughness: 0.8 });
  const jacket = new THREE.MeshStandardMaterial({ color: 0xff6a2a, roughness: 0.65 });
  const pants = new THREE.MeshStandardMaterial({ color: 0x222833, roughness: 0.9 });
  const shoes = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.8 });
  const capMat = new THREE.MeshStandardMaterial({ color: 0x151a24, roughness: 0.7 });

  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.54, 0.68, 0.32), jacket);
  torso.position.y = 1.12;
  torso.castShadow = true;
  group.add(torso);

  const hips = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.24, 0.3), pants);
  hips.position.y = 0.76;
  group.add(hips);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.185, 12, 10), skin);
  head.position.y = 1.64;
  head.castShadow = true;
  group.add(head);

  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.55), capMat);
  cap.position.y = 1.67;
  group.add(cap);
  const brim = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.04, 0.22), capMat);
  brim.position.set(0, 1.68, 0.17);
  group.add(brim);

  const limb = (w, h, d, mat, x, y) => {
    const pivot = new THREE.Group();
    pivot.position.set(x, y, 0);
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    mesh.position.y = -h / 2;
    mesh.castShadow = true;
    pivot.add(mesh);
    group.add(pivot);
    return pivot;
  };
  const armL = limb(0.15, 0.62, 0.17, jacket, -0.35, 1.42);
  const armR = limb(0.15, 0.62, 0.17, jacket, 0.35, 1.42);
  const legL = limb(0.18, 0.68, 0.2, pants, -0.14, 0.74);
  const legR = limb(0.18, 0.68, 0.2, pants, 0.14, 0.74);
  const shoeL = new THREE.Mesh(new THREE.BoxGeometry(0.19, 0.1, 0.3), shoes);
  shoeL.position.set(0, -0.72, 0.05);
  legL.add(shoeL);
  const shoeR = shoeL.clone();
  legR.add(shoeR);

  return { group, armL, armR, legL, legR };
}

export class Character {
  constructor(scene) {
    this.scene = scene;
    this.pos = new THREE.Vector3();
    this.heading = 0;
    this.speed = 0;
    this.walkPhase = 0;
    this.radius = 0.5;
    this.mesh = buildCharacter();
    scene.add(this.mesh.group);
    this.mesh.group.visible = false;
  }

  reset(x, z, heading = 0) {
    this.pos.set(x, 0, z);
    this.heading = heading;
    this.speed = 0;
    this.mesh.group.visible = true;
    this.sync(0);
  }

  hide() { this.mesh.group.visible = false; }

  update(dt, input, world) {
    const throttle = input.throttle || 0;
    const steer = input.steer || 0;
    const run = !!input.nitro;
    const target = throttle > 0.05 ? (run ? 7.6 : 4.6) * throttle : throttle < -0.05 ? 2.2 * throttle : 0;
    this.speed = damp(this.speed, target, 9, dt);
    if (Math.abs(this.speed) > 0.05) {
      this.heading += steer * 2.9 * dt * Math.sign(this.speed) * clamp(Math.abs(this.speed) / 2, 0.35, 1);
    }
    const fwd = new THREE.Vector3(Math.sin(this.heading), 0, Math.cos(this.heading));
    this.pos.addScaledVector(fwd, this.speed * dt);
    world.resolveCircle(this.pos, this.radius);
    this.sync(dt);
  }

  sync(dt) {
    const g = this.mesh.group;
    g.position.set(this.pos.x, 0.14, this.pos.z);
    g.rotation.y = this.heading;
    const moving = Math.abs(this.speed);
    this.walkPhase += dt * (2.5 + moving * 1.6);
    const swing = Math.sin(this.walkPhase * 3.4) * clamp(moving / 4, 0, 1) * 0.7;
    this.mesh.legL.rotation.x = swing;
    this.mesh.legR.rotation.x = -swing;
    this.mesh.armL.rotation.x = -swing * 0.8;
    this.mesh.armR.rotation.x = swing * 0.8;
    g.position.y = 0.14 + Math.abs(Math.sin(this.walkPhase * 3.4)) * 0.03 * clamp(moving / 4, 0, 1);
  }
}

export { CAR_COLORS, paintMat, glassMat, darkMat };

import * as THREE from '../vendor/three.module.js';
import { Rand, clamp, damp, dampAngle, dist2, mergeGeometries } from './util.js';
import { buildCarMesh, CAR_COLORS, paintMat } from './vehicles.js';
import { ROAD_COORDS } from './world.js';

const PED_COLORS = [0xff6b5e, 0x4dd0e1, 0xffd166, 0x8bd17c, 0xc792ea, 0xf5f5f5, 0x5c8dff];

/* ------------------------------------------------------------------ */
/* Traffic                                                            */
/* ------------------------------------------------------------------ */
export class TrafficSystem {
  constructor(scene, world, count = 24, seed = 9182) {
    this.scene = scene;
    this.world = world;
    this.rand = new Rand(seed);
    this.cars = [];
    const kinds = ['sedan', 'sedan', 'sedan', 'suv', 'van', 'sport'];

    for (let i = 0; i < count; i++) {
      const axis = this.rand.chance(0.5) ? 'x' : 'z';
      const road = this.rand.pick(ROAD_COORDS);
      const dir = this.rand.sign();
      const kind = this.rand.pick(kinds);
      const color = this.rand.pick(CAR_COLORS);
      const mesh = buildCarMesh({ kind, color, detailed: false });
      mesh.group.traverse((o) => { if (o.isMesh) o.castShadow = true; });
      scene.add(mesh.group);
      const car = {
        mesh, kind, color, axis, road, dir,
        t: this.rand.range(-190, 190),
        offset: this.rand.range(3.2, 5),
        speed: this.rand.range(7, 14),
        cruise: this.rand.range(7, 14),
        stun: 0,
        knock: new THREE.Vector3(),
        pos: new THREE.Vector3(),
        heading: 0,
        radius: 1.8,
      };
      this.cars.push(car);
      this._place(car);
    }
  }

  _place(car) {
    const lane = car.dir * car.offset;
    if (car.axis === 'x') {
      car.pos.set(car.t, 0, car.road + lane);
      car.heading = car.dir > 0 ? Math.PI / 2 : -Math.PI / 2;
    } else {
      car.pos.set(car.road - lane, 0, car.t);
      car.heading = car.dir > 0 ? 0 : Math.PI;
    }
    car.mesh.group.position.copy(car.pos);
    car.mesh.group.rotation.y = car.heading;
  }

  update(dt, player, time) {
    for (const car of this.cars) {
      car.stun = Math.max(0, car.stun - dt);
      const lane = car.dir * car.offset;

      // simple "don't run into the player" braking
      const fwdX = Math.sin(car.heading);
      const fwdZ = Math.cos(car.heading);
      const toPlayerX = player.pos.x - car.pos.x;
      const toPlayerZ = player.pos.z - car.pos.z;
      const ahead = toPlayerX * fwdX + toPlayerZ * fwdZ;
      const side = Math.abs(toPlayerX * fwdZ - toPlayerZ * fwdX);
      const blocked = ahead > 0 && ahead < 12 && side < 3.2;
      const targetSpeed = blocked ? Math.max(0, (ahead - 5) * 1.2) : car.cruise;

      if (car.stun <= 0) {
        car.speed = damp(car.speed, targetSpeed, 2.4, dt);
        car.t += car.dir * car.speed * dt;
        if (car.t > 202) car.t = -202;
        if (car.t < -202) car.t = 202;
        if (car.axis === 'x') {
          car.pos.set(car.t, 0, car.road + lane);
        } else {
          car.pos.set(car.road - lane, 0, car.t);
        }
      } else {
        // knocked around after a collision
        car.pos.addScaledVector(car.knock, dt);
        car.knock.multiplyScalar(Math.exp(-2.5 * dt));
        car.pos.x += Math.sin(time * 9 + car.t) * 0.02;
        car.pos.z += Math.cos(time * 11 + car.t) * 0.02;
        this.world.resolveCircle(car.pos, 1.6);
      }

      car.mesh.group.position.set(car.pos.x, 0, car.pos.z);
      car.mesh.group.rotation.y = car.heading;
      car.mesh.group.rotation.z = car.stun > 0 ? Math.sin(time * 20) * 0.05 : 0;
    }
  }

  knock(car, nx, nz, force) {
    car.stun = 1.3;
    car.knock.set(nx * force, 0, nz * force);
    car.speed = 0;
  }

  respawnFarFrom(player) {
    for (const car of this.cars) {
      if (dist2(car.pos.x, car.pos.z, player.pos.x, player.pos.z) < 55) {
        car.t = this.rand.range(-190, 190);
        if (car.axis === 'x') car.road = this.rand.pick(ROAD_COORDS);
        else car.road = this.rand.pick(ROAD_COORDS);
        this._place(car);
      }
    }
  }
}

/* ------------------------------------------------------------------ */
/* Pedestrians (instanced)                                            */
/* ------------------------------------------------------------------ */
function pedestrianGeometry() {
  const entries = [];
  const box = (w, h, d, x, y, z) => {
    const g = new THREE.BoxGeometry(w, h, d);
    g.translate(x, y, z);
    entries.push({ geo: g });
  };
  box(0.42, 0.62, 0.26, 0, 1.06, 0);
  box(0.22, 0.24, 0.24, 0, 1.55, 0);
  box(0.15, 0.62, 0.18, -0.11, 0.34, 0);
  box(0.15, 0.62, 0.18, 0.11, 0.34, 0);
  box(0.12, 0.52, 0.14, -0.28, 1.06, 0);
  box(0.12, 0.52, 0.14, 0.28, 1.06, 0);
  return mergeGeometries(entries);
}

export class PedestrianSystem {
  constructor(scene, world, count = 26, seed = 4451) {
    this.world = world;
    this.rand = new Rand(seed);
    this.peds = [];
    const geo = pedestrianGeometry();
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.85 });
    this.mesh = new THREE.InstancedMesh(geo, mat, count);
    this.mesh.castShadow = true;
    this.mesh.frustumCulled = false;
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    const color = new THREE.Color();
    for (let i = 0; i < count; i++) {
      const p = {
        pos: new THREE.Vector3(),
        target: new THREE.Vector3(),
        heading: 0,
        speed: 0,
        phase: this.rand.range(0, 10),
        scared: 0,
        down: 0,
      };
      this._newTarget(p);
      p.pos.set(p.target.x, 0, p.target.z);
      this._newTarget(p);
      color.setHex(this.rand.pick(PED_COLORS));
      this.mesh.setColorAt(i, color);
      this.peds.push(p);
    }
    this.mesh.instanceColor.needsUpdate = true;
    scene.add(this.mesh);
    this._m = new THREE.Matrix4();
    this._q = new THREE.Quaternion();
    this._s = new THREE.Vector3(1, 1, 1);
  }

  _newTarget(p) {
    const pt = this.world.randomSidewalkPoint(this.rand);
    p.target.set(pt.x, 0, pt.z);
  }

  update(dt, player, time) {
    const m = this._m, q = this._q, s = this._s;
    for (let i = 0; i < this.peds.length; i++) {
      const p = this.peds[i];
      const d = dist2(p.pos.x, p.pos.z, player.pos.x, player.pos.z);
      p.scared = Math.max(0, p.scared - dt);
      if (d < 11 && Math.abs(player.speed || 0) > 3) p.scared = 2.2;
      if (p.down > 0) {
        p.down -= dt;
        m.makeTranslation(p.pos.x, 0.2, p.pos.z);
        m.multiply(new THREE.Matrix4().makeRotationZ(Math.PI / 2));
        this.mesh.setMatrixAt(i, m);
        continue;
      }
      if (p.scared > 0) {
        const away = new THREE.Vector3(p.pos.x - player.pos.x, 0, p.pos.z - player.pos.z).normalize();
        p.target.set(
          clamp(p.pos.x + away.x * 26, -220, 220), 0,
          clamp(p.pos.z + away.z * 26, -220, 220),
        );
      }
      const dx = p.target.x - p.pos.x;
      const dz = p.target.z - p.pos.z;
      const dist = Math.hypot(dx, dz);
      if (dist < 2) this._newTarget(p);
      const desired = Math.atan2(dx, dz);
      p.heading = dampAngle(p.heading, desired, 6, dt);
      const targetSpeed = p.scared > 0 ? 5.2 : 1.35;
      p.speed = damp(p.speed, targetSpeed, 5, dt);
      p.pos.x += Math.sin(p.heading) * p.speed * dt;
      p.pos.z += Math.cos(p.heading) * p.speed * dt;
      if (p.scared <= 0) this.world.resolveCircle(p.pos, 0.4);
      p.phase += dt * (2 + p.speed * 2.2);
      const bob = Math.abs(Math.sin(p.phase * 3)) * 0.05 * clamp(p.speed, 0, 1.5);
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), p.heading);
      m.compose(new THREE.Vector3(p.pos.x, 0.14 + bob, p.pos.z), q, s);
      this.mesh.setMatrixAt(i, m);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  hit(ped) {
    ped.down = 3.5;
    ped.scared = 0;
  }
}

/* ------------------------------------------------------------------ */
/* Police                                                             */
/* ------------------------------------------------------------------ */
export class PoliceSystem {
  constructor(scene, world, seed = 777) {
    this.scene = scene;
    this.world = world;
    this.rand = new Rand(seed);
    this.cars = [];
    this.spawnTimer = 0;
    this.flash = 0;
  }

  _spawn(player, wanted) {
    const angle = this.rand.range(0, Math.PI * 2);
    const dist = this.rand.range(70, 105);
    let x = player.pos.x + Math.cos(angle) * dist;
    let z = player.pos.z + Math.sin(angle) * dist;
    x = clamp(x, -200, 200);
    z = clamp(z, -200, 200);
    // snap to nearest road for a clean approach
    const rx = ROAD_COORDS.reduce((a, b) => (Math.abs(b - x) < Math.abs(a - x) ? b : a));
    const rz = ROAD_COORDS.reduce((a, b) => (Math.abs(b - z) < Math.abs(a - z) ? b : a));
    if (Math.abs(rx - x) < Math.abs(rz - z)) x = rx + this.rand.sign() * 4;
    else z = rz + this.rand.sign() * 4;

    const mesh = buildCarMesh({ kind: 'police', color: 0xf2f0e8, detailed: false });
    mesh.group.traverse((o) => { if (o.isMesh) o.castShadow = true; });
    this.scene.add(mesh.group);
    const cop = {
      mesh,
      pos: new THREE.Vector3(x, 0, z),
      heading: Math.atan2(player.pos.x - x, player.pos.z - z),
      speed: 0,
      hp: 120,
      shootTimer: this.rand.range(1.5, 3),
      stuck: 0,
      radius: 1.9,
      active: true,
      spawnAnim: 0.6,
    };
    this.cars.push(cop);
    mesh.group.position.copy(cop.pos);
    return cop;
  }

  update(dt, player, wanted, time, callbacks) {
    this.flash += dt;
    const maxCops = Math.min(7, Math.floor(wanted * 1.6));
    const alive = this.cars.filter((c) => c.active);
    this.spawnTimer -= dt;
    if (alive.length < maxCops && this.spawnTimer <= 0) {
      this._spawn(player, wanted);
      this.spawnTimer = 1.4;
    }

    for (const cop of this.cars) {
      if (!cop.active) continue;
      cop.spawnAnim = Math.max(0, cop.spawnAnim - dt);
      const dx = player.pos.x - cop.pos.x;
      const dz = player.pos.z - cop.pos.z;
      const dist = Math.hypot(dx, dz);

      // flashing lights
      const phase = Math.sin(time * 12 + cop.pos.x) > 0;
      if (cop.mesh.lightbar) {
        cop.mesh.lightbar.red.material.color.setHex(phase ? 0xff2038 : 0x3a0008);
        cop.mesh.lightbar.blue.material.color.setHex(phase ? 0x0a1a4a : 0x2f7bff);
      }

      if (dist > 3) {
        const desired = Math.atan2(dx, dz);
        const turn = dampAngle(cop.heading, desired, 2.6, dt);
        cop.heading = turn;
      }
      const targetSpeed = dist > 18 ? 34 : dist > 8 ? 20 : 8;
      cop.speed = damp(cop.speed, targetSpeed, 1.9, dt);
      cop.pos.x += Math.sin(cop.heading) * cop.speed * dt;
      cop.pos.z += Math.cos(cop.heading) * cop.speed * dt;
      const hit = this.world.resolveCircle(cop.pos, cop.radius);
      if (hit) {
        cop.speed *= 0.55;
        cop.stuck = 0.8;
        // slide around corners
        cop.heading += Math.sign(Math.sin(cop.heading) * hit.nx + Math.cos(cop.heading) * hit.nz) * 0.9 * dt;
      }
      cop.pos.x = clamp(cop.pos.x, -228, 228);
      cop.pos.z = clamp(cop.pos.z, -228, 228);

      cop.mesh.group.position.set(cop.pos.x, 0, cop.pos.z);
      cop.mesh.group.rotation.y = cop.heading;
      cop.mesh.group.rotation.z = Math.sin(time * 8 + cop.pos.x) * 0.02;

      // shooting
      if (dist < 26 && wanted >= 2) {
        cop.shootTimer -= dt;
        if (cop.shootTimer <= 0) {
          cop.shootTimer = this.rand.range(1.6, 3.2);
          callbacks.onShoot?.(cop, dist);
        }
      }

      // busted check
      if (dist < 6.2 && Math.abs(player.speed) < 4.5) {
        cop.bustTimer = (cop.bustTimer || 0) + dt;
        if (cop.bustTimer > 1.1) callbacks.onBusted?.();
      } else {
        cop.bustTimer = 0;
      }
    }

    // remove inactive after a moment
    this.cars = this.cars.filter((c) => c.active || (c.removeTimer = (c.removeTimer || 0) + dt) < 1.2);
    for (const c of this.cars) {
      if (!c.active) c.mesh.group.visible = false;
    }
  }

  damage(cop, amount, callbacks) {
    if (!cop.active) return;
    cop.hp -= amount;
    if (cop.hp <= 0) {
      cop.active = false;
      cop.mesh.group.visible = false;
      callbacks.onCopWrecked?.(cop);
    }
  }

  clear() {
    for (const c of this.cars) {
      this.scene.remove(c.mesh.group);
      c.mesh.group.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
      });
    }
    this.cars = [];
  }

  dispose() { this.clear(); }
}

import * as THREE from '../vendor/three.module.js';
import { softCircleTexture, glowTexture } from './util.js';

const PARTICLE_VERT = `
  attribute float size;
  attribute float alpha;
  attribute vec3 pcolor;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = pcolor;
    vAlpha = alpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = size * (420.0 / max(1.0, -mv.z));
    gl_Position = projectionMatrix * mv;
  }
`;
const PARTICLE_FRAG = `
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec2 uv = gl_PointCoord - 0.5;
    float d = length(uv);
    float a = smoothstep(0.5, 0.06, d);
    gl_FragColor = vec4(vColor, a * vAlpha);
  }
`;

class ParticlePool {
  constructor(scene, max, blending = THREE.NormalBlending, gravity = 4) {
    this.max = max;
    this.gravity = gravity;
    this.i = 0;
    this.alive = 0;
    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(max * 3);
    this.col = new Float32Array(max * 3);
    this.size = new Float32Array(max);
    this.alpha = new Float32Array(max);
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('pcolor', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('size', new THREE.BufferAttribute(this.size, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alpha, 1).setUsage(THREE.DynamicDrawUsage));
    this.geo = geo;
    this.mat = new THREE.ShaderMaterial({
      vertexShader: PARTICLE_VERT,
      fragmentShader: PARTICLE_FRAG,
      transparent: true,
      depthWrite: false,
      blending,
    });
    this.points = new THREE.Points(geo, this.mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.particles = Array.from({ length: max }, () => ({
      life: 0, maxLife: 1, vx: 0, vy: 0, vz: 0, drag: 0.96, grow: 0, size0: 1, alpha0: 1,
    }));
    this._c = new THREE.Color();
  }

  spawn(x, y, z, opts = {}) {
    const idx = this.i;
    this.i = (this.i + 1) % this.max;
    const p = this.particles[idx];
    p.life = p.maxLife = opts.life ?? 0.8;
    p.vx = opts.vx ?? 0; p.vy = opts.vy ?? 0; p.vz = opts.vz ?? 0;
    p.drag = opts.drag ?? 0.96;
    p.grow = opts.grow ?? 0;
    p.size0 = opts.size ?? 1;
    p.alpha0 = opts.alpha ?? 1;
    this.pos[idx * 3] = x; this.pos[idx * 3 + 1] = y; this.pos[idx * 3 + 2] = z;
    const c = this._c.set(opts.color ?? 0xffffff);
    this.col[idx * 3] = c.r; this.col[idx * 3 + 1] = c.g; this.col[idx * 3 + 2] = c.b;
    this.size[idx] = p.size0;
    this.alpha[idx] = p.alpha0;
  }

  update(dt) {
    let any = false;
    for (let k = 0; k < this.max; k++) {
      const p = this.particles[k];
      if (p.life <= 0) continue;
      any = true;
      p.life -= dt;
      if (p.life <= 0) { this.alpha[k] = 0; this.size[k] = 0; continue; }
      const t = p.life / p.maxLife;
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vy *= Math.pow(p.drag, dt * 60);
      p.vz *= Math.pow(p.drag, dt * 60);
      p.vy -= this.gravity * dt;
      this.pos[k * 3] += p.vx * dt;
      this.pos[k * 3 + 1] += p.vy * dt;
      this.pos[k * 3 + 2] += p.vz * dt;
      this.size[k] = p.size0 * (1 + p.grow * (1 - t));
      this.alpha[k] = p.alpha0 * Math.min(1, t * 2.4);
    }
    if (any) {
      this.geo.attributes.position.needsUpdate = true;
      this.geo.attributes.size.needsUpdate = true;
      this.geo.attributes.alpha.needsUpdate = true;
      this.geo.attributes.pcolor.needsUpdate = true;
    }
  }
}

/* ------------------------------------------------------------------ */
export class FX {
  constructor(scene) {
    this.scene = scene;
    this.smoke = new ParticlePool(scene, 320, THREE.NormalBlending, -0.6);
    this.spark = new ParticlePool(scene, 380, THREE.AdditiveBlending, 9);
    this.glow = new ParticlePool(scene, 160, THREE.AdditiveBlending, 0);
    this.buildSkids();
    this.buildFlashes();
    this.flashes = [];
  }

  buildSkids() {
    this.skidMax = 520;
    this.skidIndex = 0;
    const geo = new THREE.PlaneGeometry(0.46, 1.9);
    geo.rotateX(-Math.PI / 2);
    const mat = new THREE.MeshBasicMaterial({
      color: 0x090909, transparent: true, opacity: 0.55, depthWrite: false,
    });
    this.skids = new THREE.InstancedMesh(geo, mat, this.skidMax);
    this.skids.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.skids.frustumCulled = false;
    this.skids.renderOrder = 1;
    const m = new THREE.Matrix4();
    m.makeScale(0, 0, 0);
    for (let i = 0; i < this.skidMax; i++) this.skids.setMatrixAt(i, m);
    this.skids.count = this.skidMax;
    this.scene.add(this.skids);
    this._m = new THREE.Matrix4();
    this._q = new THREE.Quaternion();
    this._up = new THREE.Vector3(0, 1, 0);
    this._v = new THREE.Vector3();
    this._s = new THREE.Vector3(1, 1, 1);
  }

  buildFlashes() {
    this.flashTex = glowTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)');
  }

  skid(x, z, heading, strength = 1) {
    const i = this.skidIndex;
    this.skidIndex = (this.skidIndex + 1) % this.skidMax;
    this._q.setFromAxisAngle(this._up, heading);
    this._v.set(x, 0.05, z);
    this._s.set(1, 1, 0.8 + strength * 0.4);
    this._m.compose(this._v, this._q, this._s);
    this.skids.setMatrixAt(i, this._m);
    this.skids.instanceMatrix.needsUpdate = true;
  }

  tireSmoke(x, z, strength = 1, side = 0) {
    const n = Math.ceil(strength * 2);
    for (let i = 0; i < n; i++) {
      this.smoke.spawn(
        x + (Math.random() - 0.5) * 0.6,
        0.35,
        z + (Math.random() - 0.5) * 0.6,
        {
          vx: (Math.random() - 0.5) * 1.6 + side * 0.4,
          vy: 0.5 + Math.random() * 1.1,
          vz: (Math.random() - 0.5) * 1.6,
          size: 0.55 + Math.random() * 0.5,
          grow: 3.4,
          life: 0.6 + Math.random() * 0.7,
          alpha: 0.22 + Math.random() * 0.16,
          color: 0xdad6d0,
          drag: 0.9,
        },
      );
    }
  }

  dust(x, z, strength = 1) {
    for (let i = 0; i < Math.ceil(strength * 2); i++) {
      this.smoke.spawn(x + (Math.random() - 0.5) * 2, 0.2, z + (Math.random() - 0.5) * 2, {
        vx: (Math.random() - 0.5) * 3, vy: 0.7 + Math.random(), vz: (Math.random() - 0.5) * 3,
        size: 0.7, grow: 2.5, life: 0.9, alpha: 0.16, color: 0xc9ae85, drag: 0.92,
      });
    }
  }

  impact(x, y, z, nx = 0, nz = 0, strength = 1) {
    const n = Math.min(30, 8 + Math.floor(strength * 2));
    for (let i = 0; i < n; i++) {
      this.spark.spawn(x, y, z, {
        vx: (Math.random() - 0.5) * 7 + nx * strength * 0.6,
        vy: Math.random() * 5,
        vz: (Math.random() - 0.5) * 7 + nz * strength * 0.6,
        size: 0.16 + Math.random() * 0.22,
        life: 0.3 + Math.random() * 0.45,
        alpha: 1,
        color: Math.random() > 0.35 ? 0xffc36b : 0xfff3c4,
        drag: 0.9,
      });
    }
    this.flash(x, y, z, 0xffb15c, 2.2, 0.16);
  }

  explosion(x, y, z) {
    for (let i = 0; i < 26; i++) {
      this.smoke.spawn(x + (Math.random() - 0.5) * 2, y + Math.random() * 1.4, z + (Math.random() - 0.5) * 2, {
        vx: (Math.random() - 0.5) * 8, vy: 2 + Math.random() * 5, vz: (Math.random() - 0.5) * 8,
        size: 1.2 + Math.random() * 1.4, grow: 3, life: 1.1 + Math.random() * 1.2,
        alpha: 0.5, color: 0x2a2723, drag: 0.9,
      });
    }
    for (let i = 0; i < 60; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = 3 + Math.random() * 13;
      this.spark.spawn(x, y + 0.5, z, {
        vx: Math.cos(a) * s, vy: Math.random() * 12, vz: Math.sin(a) * s,
        size: 0.2 + Math.random() * 0.45, life: 0.4 + Math.random() * 0.8, alpha: 1,
        color: Math.random() > 0.4 ? 0xff9a2a : 0xffe9a8, drag: 0.94,
      });
    }
    this.flash(x, y + 1, z, 0xffa040, 12, 0.45);
  }

  pickup(x, y, z, color = 0x7dff6e) {
    for (let i = 0; i < 14; i++) {
      const a = Math.random() * Math.PI * 2;
      this.glow.spawn(x, y + 0.4, z, {
        vx: Math.cos(a) * 2.2, vy: 2 + Math.random() * 2.5, vz: Math.sin(a) * 2.2,
        size: 0.28 + Math.random() * 0.25, life: 0.5 + Math.random() * 0.4, alpha: 1,
        color, drag: 0.92,
      });
    }
    this.flash(x, y + 0.5, z, color, 3.2, 0.28);
  }

  nitro(x, y, z, heading) {
    const back = new THREE.Vector3(-Math.sin(heading), 0, -Math.cos(heading));
    for (let i = 0; i < 2; i++) {
      this.glow.spawn(x + back.x * 1.5 + (Math.random() - 0.5), y + 0.4, z + back.z * 1.5 + (Math.random() - 0.5), {
        vx: back.x * 6 + (Math.random() - 0.5) * 2,
        vy: 0.4,
        vz: back.z * 6 + (Math.random() - 0.5) * 2,
        size: 0.5 + Math.random() * 0.5, life: 0.22, alpha: 0.9,
        color: Math.random() > 0.4 ? 0x5ee6ff : 0x2f7bff, drag: 0.86,
      });
    }
  }

  gunshot(x, y, z, tx, ty, tz) {
    const dx = tx - x, dy = ty - y, dz = tz - z;
    const len = Math.hypot(dx, dy, dz) || 1;
    const steps = 7;
    for (let i = 0; i < steps; i++) {
      const t = i / steps;
      this.glow.spawn(x + dx * t, y + dy * t, z + dz * t, {
        vx: (Math.random() - 0.5) * 0.8, vy: 0.3, vz: (Math.random() - 0.5) * 0.8,
        size: 0.22 + (1 - t) * 0.2, life: 0.16 + Math.random() * 0.1, alpha: 0.9,
        color: 0xffe2a0, drag: 0.8,
      });
    }
    this.flash(x, y, z, 0xffd28a, 1.8, 0.08);
  }

  flash(x, y, z, color, size, duration = 0.3) {
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.flashTex, color, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
    sprite.position.set(x, y, z);
    sprite.scale.set(size, size, 1);
    this.scene.add(sprite);
    this.flashes.push({ sprite, life: duration, maxLife: duration, size });
  }

  update(dt, player, time) {
    this.smoke.update(dt);
    this.spark.update(dt);
    this.glow.update(dt);
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.life -= dt;
      if (f.life <= 0) {
        this.scene.remove(f.sprite);
        f.sprite.material.dispose();
        this.flashes.splice(i, 1);
        continue;
      }
      const t = f.life / f.maxLife;
      f.sprite.material.opacity = t * 0.9;
      const s = f.size * (1 + (1 - t) * 1.6);
      f.sprite.scale.set(s, s, 1);
    }
  }
}

/* Lightweight WebAudio synth: engine, tires, siren, impacts, and a synthwave loop. */

const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.started = false;
    this.muted = false;
    this.musicOn = true;
    this.ready = false;
  }

  init() {
    if (this.started) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.started = true;
    const ctx = this.ctx;

    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    this.master.connect(ctx.destination);

    this.sfx = ctx.createGain();
    this.sfx.gain.value = 0.9;
    this.sfx.connect(this.master);

    this.music = ctx.createGain();
    this.music.gain.value = 0.16;
    this.music.connect(this.master);

    this.noiseBuf = this._noiseBuffer(2);

    this._buildEngine();
    this._buildTires();
    this._buildWind();
    this._buildSiren();
    this._startMusic();
    this.ready = true;
  }

  _noiseBuffer(seconds) {
    const ctx = this.ctx;
    const buf = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    return buf;
  }

  _loopNoise(gainValue = 0) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    const g = this.ctx.createGain();
    g.gain.value = gainValue;
    src.connect(g);
    src.start();
    return { src, gain: g };
  }

  _buildEngine() {
    const ctx = this.ctx;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 420;
    this.engineFilter.Q.value = 3;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.sfx);

    this.engOsc1 = ctx.createOscillator();
    this.engOsc1.type = 'sawtooth';
    this.engOsc1.frequency.value = 45;
    this.engOsc2 = ctx.createOscillator();
    this.engOsc2.type = 'square';
    this.engOsc2.frequency.value = 70;
    const g1 = ctx.createGain(); g1.gain.value = 0.55;
    const g2 = ctx.createGain(); g2.gain.value = 0.28;
    this.engOsc1.connect(g1); g1.connect(this.engineGain);
    this.engOsc2.connect(g2); g2.connect(this.engineGain);
    this.engOsc1.start();
    this.engOsc2.start();
  }

  _buildTires() {
    const n = this._loopNoise(0);
    this.tireGain = n.gain;
    this.tireFilter = this.ctx.createBiquadFilter();
    this.tireFilter.type = 'bandpass';
    this.tireFilter.frequency.value = 1900;
    this.tireFilter.Q.value = 0.9;
    n.gain.disconnect();
    n.gain.connect(this.tireFilter);
    this.tireFilter.connect(this.sfx);
  }

  _buildWind() {
    const n = this._loopNoise(0);
    this.windGain = n.gain;
    this.windFilter = this.ctx.createBiquadFilter();
    this.windFilter.type = 'lowpass';
    this.windFilter.frequency.value = 600;
    n.gain.disconnect();
    n.gain.connect(this.windFilter);
    this.windFilter.connect(this.sfx);
  }

  _buildSiren() {
    const ctx = this.ctx;
    this.sirenGain = ctx.createGain();
    this.sirenGain.gain.value = 0;
    const osc = ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.value = 720;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 1500;
    osc.connect(filter);
    filter.connect(this.sirenGain);
    this.sirenGain.connect(this.sfx);
    osc.start();
    this.sirenOsc = osc;
  }

  /* ---------------- music ---------------- */
  _startMusic() {
    this.bpm = 96;
    this.stepDur = 60 / this.bpm / 4;
    this.step = 0;
    this.nextTime = this.ctx.currentTime + 0.15;
    this.musicTimer = setInterval(() => this._schedule(), 90);
  }

  _schedule() {
    if (!this.ready || !this.musicOn) return;
    const ctx = this.ctx;
    while (this.nextTime < ctx.currentTime + 0.22) {
      this._playStep(this.step, this.nextTime);
      this.nextTime += this.stepDur;
      this.step = (this.step + 1) % 32;
    }
  }

  _playStep(step, t) {
    const ctx = this.ctx;
    const bar = step % 16;
    // kick
    if (bar % 4 === 0) {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(130, t);
      o.frequency.exponentialRampToValueAtTime(42, t + 0.16);
      g.gain.setValueAtTime(0.55, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
      o.connect(g); g.connect(this.music);
      o.start(t); o.stop(t + 0.32);
    }
    // snare
    if (bar === 4 || bar === 12) {
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass'; f.frequency.value = 1700; f.Q.value = 0.8;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.18, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.16);
      src.connect(f); f.connect(g); g.connect(this.music);
      src.start(t, Math.random()); src.stop(t + 0.2);
    }
    // hats
    if (bar % 2 === 1) {
      const src = ctx.createBufferSource();
      src.buffer = this.noiseBuf;
      const f = ctx.createBiquadFilter();
      f.type = 'highpass'; f.frequency.value = 7000;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.05, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
      src.connect(f); f.connect(g); g.connect(this.music);
      src.start(t, Math.random()); src.stop(t + 0.07);
    }
    // bass line (A minor-ish)
    const bassNotes = [33, 33, 33, 36, 33, 33, 31, 33, 33, 33, 36, 38, 33, 31, 29, 31];
    if (bar % 2 === 0) {
      const n = bassNotes[(bar / 2) | 0];
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = 520;
      o.type = 'sawtooth';
      o.frequency.value = NOTE(n);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.16, t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + this.stepDur * 1.9);
      o.connect(f); f.connect(g); g.connect(this.music);
      o.start(t); o.stop(t + this.stepDur * 2.1);
    }
    // arpeggio sparkle
    const arp = [69, 72, 76, 72, 69, 76, 81, 76];
    if (step % 2 === 0) {
      const n = arp[(step / 2) % arp.length];
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'triangle';
      o.frequency.value = NOTE(n);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.035, t + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, t + 0.22);
      o.connect(g); g.connect(this.music);
      o.start(t); o.stop(t + 0.25);
    }
    // pad every 2 bars
    if (step === 0) {
      for (const n of [45, 48, 52]) {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        const f = ctx.createBiquadFilter();
        f.type = 'lowpass'; f.frequency.value = 700;
        o.type = 'sawtooth';
        o.frequency.value = NOTE(n);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(0.028, t + 1.2);
        g.gain.linearRampToValueAtTime(0.0001, t + 7.4);
        o.connect(f); f.connect(g); g.connect(this.music);
        o.start(t); o.stop(t + 7.6);
      }
    }
  }

  /* ---------------- per-frame ---------------- */
  update(state) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const speed = Math.abs(state.speed || 0);
    const throttle = Math.max(0, state.throttle || 0);
    const driving = !!state.driving;
    const ratio = Math.min(1, speed / 55);

    const engineVol = driving ? (0.055 + throttle * 0.05 + ratio * 0.03) : 0;
    this.engineGain.gain.setTargetAtTime(engineVol, t, 0.1);
    const base = 38 + speed * 1.55 + throttle * 8;
    this.engOsc1.frequency.setTargetAtTime(base, t, 0.08);
    this.engOsc2.frequency.setTargetAtTime(base * 1.52, t, 0.08);
    this.engineFilter.frequency.setTargetAtTime(380 + speed * 26 + throttle * 200, t, 0.1);

    const screech = driving ? Math.min(0.16, (state.drift || 0) * 0.16) : 0;
    this.tireGain.gain.setTargetAtTime(screech, t, 0.06);
    this.tireFilter.frequency.setTargetAtTime(1500 + (state.drift || 0) * 900, t, 0.1);

    const wind = driving ? ratio * ratio * 0.09 : 0.01;
    this.windGain.gain.setTargetAtTime(wind, t, 0.2);

    // siren
    let siren = 0;
    if (state.copDistance != null && state.wanted > 0) {
      siren = Math.max(0, 1 - state.copDistance / 90) * 0.07;
    }
    this.sirenGain.gain.setTargetAtTime(siren, t, 0.15);
    if (siren > 0.001) {
      const phase = Math.sin(t * 5.5) > 0 ? 780 : 560;
      this.sirenOsc.frequency.setTargetAtTime(phase, t, 0.03);
    }
  }

  /* ---------------- one-shots ---------------- */
  crash(strength = 1) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 1400;
    const g = ctx.createGain();
    g.gain.setValueAtTime(Math.min(0.5, 0.12 + strength * 0.02), t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
    src.connect(f); f.connect(g); g.connect(this.sfx);
    src.start(t, Math.random()); src.stop(t + 0.4);

    const o = ctx.createOscillator();
    const og = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(110, t);
    o.frequency.exponentialRampToValueAtTime(38, t + 0.2);
    og.gain.setValueAtTime(Math.min(0.4, 0.1 + strength * 0.02), t);
    og.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
    o.connect(og); og.connect(this.sfx);
    o.start(t); o.stop(t + 0.28);
  }

  beep(freq = 880, dur = 0.12, type = 'sine', vol = 0.16) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.sfx);
    o.start(t); o.stop(t + dur + 0.02);
  }

  pickup() { this.beep(880, 0.09); setTimeout(() => this.beep(1320, 0.13), 70); }
  cash() { this.beep(1040, 0.07, 'triangle', 0.12); setTimeout(() => this.beep(1560, 0.1, 'triangle', 0.1), 60); }
  missionComplete() {
    [660, 880, 1100, 1320].forEach((f, i) => setTimeout(() => this.beep(f, 0.18, 'triangle', 0.13), i * 110));
  }
  busted() {
    this.beep(300, 0.3, 'sawtooth', 0.2);
    setTimeout(() => this.beep(180, 0.5, 'sawtooth', 0.18), 220);
  }
  gunshot() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass'; f.frequency.value = 900; f.Q.value = 0.6;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.16, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    src.connect(f); f.connect(g); g.connect(this.sfx);
    src.start(t, Math.random()); src.stop(t + 0.14);
  }
  nitroWhoosh() {
    if (!this.ready) return;
    this.beep(220, 0.3, 'sawtooth', 0.05);
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.7, this.ctx.currentTime, 0.05);
  }

  setMusic(on) {
    this.musicOn = on;
    if (this.music) this.music.gain.setTargetAtTime(on ? 0.16 : 0, this.ctx.currentTime, 0.1);
  }

  suspend() { if (this.ctx && this.ctx.state === 'running') this.ctx.suspend(); }
  resume() { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); }
}

import { clamp } from './util.js';
import { BOUNDARY, ROAD_COORDS } from './world.js';

const $ = (id) => document.getElementById(id);

export class UI {
  constructor(world) {
    this.world = world;
    this.el = {
      hud: $('hud'), touch: $('touch'),
      start: $('start'), pause: $('pause'), over: $('over'),
      speedVal: $('speedVal'), gauge: $('gaugeFill'), gear: $('gear'),
      cash: $('cash'), cashBox: $('cashBox'),
      health: $('healthBar'), nitro: $('nitroBar'),
      wanted: $('wanted'),
      missionName: $('missionName'), missionObjective: $('missionObjective'),
      missionDist: $('missionDist'), missionTimer: $('missionTimer'),
      missionBar: $('missionBar'), missionPanel: $('missionPanel'),
      compass: $('compass'), compassArrow: $('compassArrow'),
      minimap: $('minimap'),
      modeHint: $('modeHint'), actionBtn: $('actionBtn'),
      toasts: $('toasts'),
      pauseCash: $('pauseCash'), pauseWanted: $('pauseWanted'), pauseJobs: $('pauseJobs'),
      overKicker: $('overKicker'), overTitle: $('overTitle'), overText: $('overText'),
      overCash: $('overCash'), overJobs: $('overJobs'), overBest: $('overBest'),
      bestScore: $('bestScore'),
      qualityBtn: $('qualityBtn'), soundBtn: $('soundBtn'),
      loading: $('loading'), rotateHint: $('rotateHint'),
    };
    this.stars = [];
    for (let i = 0; i < 5; i++) {
      const s = document.createElement('span');
      s.className = 'star';
      this.el.wanted.appendChild(s);
      this.stars.push(s);
    }
    this.lastCash = -1;
    this.lastStars = -1;
    this.lastWanted = 0;
    this.minimapTimer = 0;
    this.mctx = this.el.minimap.getContext('2d');
    this.mapSize = this.el.minimap.width;
    this.range = 150;
    this._buildStaticMap();
    this.compassTimer = 0;
  }

  _buildStaticMap() {
    const S = 1024;
    const WORLD = 540;
    const scale = S / WORLD;
    const c = document.createElement('canvas');
    c.width = S; c.height = S;
    const ctx = c.getContext('2d');
    const wx = (x) => (x + WORLD / 2) * scale;
    const wz = (z) => (z + WORLD / 2) * scale;

    // water
    ctx.fillStyle = '#08202c';
    ctx.fillRect(0, 0, S, S);
    // beach
    ctx.fillStyle = '#5a4a34';
    ctx.fillRect(wx(-BOUNDARY - 8), wz(-BOUNDARY - 8), (BOUNDARY * 2 + 16) * scale, (BOUNDARY * 2 + 16) * scale);
    // city ground
    ctx.fillStyle = '#161920';
    ctx.fillRect(wx(-235), wz(-235), 470 * scale, 470 * scale);

    // blocks
    ctx.fillStyle = '#23262e';
    for (const bx of [-160, -96, -32, 32, 96, 160]) {
      for (const bz of [-160, -96, -32, 32, 96, 160]) {
        ctx.fillRect(wx(bx - 24), wz(bz - 24), 48 * scale, 48 * scale);
      }
    }

    // parks
    ctx.fillStyle = '#2c5a33';
    for (const p of this.world.parks) {
      ctx.fillRect(wx(p.x - p.w / 2), wz(p.z - p.d / 2), p.w * scale, p.d * scale);
    }

    // roads
    ctx.strokeStyle = '#41454f';
    ctx.lineWidth = 16 * scale;
    ctx.lineCap = 'butt';
    for (const r of ROAD_COORDS) {
      ctx.beginPath(); ctx.moveTo(wx(r), wz(-192)); ctx.lineTo(wx(r), wz(192)); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(wx(-192), wz(r)); ctx.lineTo(wx(192), wz(r)); ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(255,210,120,0.20)';
    ctx.lineWidth = 1.4;
    for (const r of ROAD_COORDS) {
      ctx.beginPath(); ctx.moveTo(wx(r), wz(-192)); ctx.lineTo(wx(r), wz(192)); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(wx(-192), wz(r)); ctx.lineTo(wx(192), wz(r)); ctx.stroke();
    }

    // buildings
    for (const b of this.world.buildings) {
      const shade = 74 + Math.min(50, b.h * 0.5);
      ctx.fillStyle = `rgb(${shade},${shade + 3},${shade + 9})`;
      ctx.fillRect(wx(b.x - b.w / 2), wz(b.z - b.d / 2), b.w * scale, b.d * scale);
    }

    // seawall
    ctx.strokeStyle = 'rgba(220,200,160,0.35)';
    ctx.lineWidth = 2;
    ctx.strokeRect(wx(-BOUNDARY), wz(-BOUNDARY), BOUNDARY * 2 * scale, BOUNDARY * 2 * scale);

    this.staticMap = c;
    this.staticScale = scale;
  }

  setStarted(started) {
    this.el.hud.classList.toggle('hidden', !started);
    this.el.touch.classList.toggle('hidden', !started);
    this.el.start.classList.toggle('hidden', started);
  }

  showPause(show, state) {
    this.el.pause.classList.toggle('hidden', !show);
    if (show) {
      this.el.pauseCash.textContent = '$' + Math.round(state.cash).toLocaleString('en-US');
      this.el.pauseWanted.textContent = `${Math.ceil(state.wanted)}★`;
      this.el.pauseJobs.textContent = state.jobs;
      this.el.qualityBtn.textContent = `QUALITY: ${state.quality.toUpperCase()}`;
      this.el.soundBtn.textContent = `SOUND: ${state.muted ? 'OFF' : 'ON'}`;
    }
  }

  showOver(show, kind, state, best) {
    this.el.over.classList.toggle('hidden', !show);
    if (!show) return;
    this.el.overKicker.textContent = kind === 'busted' ? 'THE HEAT WON' : 'TOTALED';
    this.el.overTitle.textContent = kind === 'busted' ? 'BUSTED' : 'WRECKED';
    this.el.overText.textContent = kind === 'busted'
      ? 'Cuffed on the curb. The city keeps your cut.'
      : 'The ride is scrap. You walk away — barely.';
    this.el.overCash.textContent = '$' + Math.round(state.cash).toLocaleString('en-US');
    this.el.overJobs.textContent = state.jobs;
    this.el.overBest.textContent = '$' + Math.round(best).toLocaleString('en-US');
  }

  setBest(best) {
    this.el.bestScore.textContent = '$' + Math.round(best).toLocaleString('en-US');
  }

  toast(text, kind = '') {
    const t = document.createElement('div');
    t.className = 'toast ' + kind;
    t.textContent = text;
    this.el.toasts.appendChild(t);
    setTimeout(() => t.remove(), 3200);
    while (this.el.toasts.children.length > 4) this.el.toasts.firstChild.remove();
  }

  setAction(label, visible) {
    this.el.actionBtn.textContent = label;
    this.el.actionBtn.classList.toggle('hidden', !visible);
    this.el.modeHint.classList.toggle('hidden', !visible);
    this.el.modeHint.textContent = label.includes('STEAL') ? 'E · STEAL THIS RIDE' : 'E · ENTER VEHICLE';
  }

  update(state, dt) {
    const speed = Math.round(state.kmh);
    this.el.speedVal.textContent = speed;
    const ratio = clamp(state.kmh / 260, 0, 1);
    this.el.gauge.style.strokeDashoffset = String(358 * (1 - ratio));
    this.el.gauge.style.stroke = state.boosting ? '#37e6ff' : ratio > 0.72 ? '#ff2d6f' : '#ff7a1a';
    this.el.gear.textContent = state.gear;

    const cashRounded = Math.round(state.cash);
    if (cashRounded !== this.lastCash) {
      this.el.cash.textContent = cashRounded.toLocaleString('en-US');
      if (this.lastCash >= 0 && cashRounded > this.lastCash) {
        this.el.cashBox.classList.remove('bump');
        void this.el.cashBox.offsetWidth;
        this.el.cashBox.classList.add('bump');
      }
      this.lastCash = cashRounded;
    }

    this.el.health.style.width = clamp(state.health, 0, 100) + '%';
    this.el.nitro.style.width = clamp(state.nitro, 0, 100) + '%';

    const starCount = Math.round(state.wanted);
    if (starCount !== this.lastStars) {
      this.stars.forEach((s, i) => {
        const on = i < starCount;
        if (on && !s.classList.contains('on')) {
          s.classList.add('pulse');
          setTimeout(() => s.classList.remove('pulse'), 460);
        }
        s.classList.toggle('on', on);
      });
      this.lastStars = starCount;
    }

    // mission panel
    if (state.mission) {
      const m = state.mission;
      this.el.missionName.textContent = m.name;
      this.el.missionObjective.textContent = `CHECKPOINT ${m.index + 1} / ${m.total}`;
      this.el.missionDist.textContent = Math.max(0, Math.round(state.missionDist)) + ' m';
      const time = Math.max(0, state.missionTime);
      this.el.missionTimer.textContent = `${Math.floor(time / 60)}:${String(Math.floor(time % 60)).padStart(2, '0')}`;
      this.el.missionBar.style.width = clamp((time / m.time) * 100, 0, 100) + '%';
      this.el.missionPanel.classList.toggle('urgent', time < 10);
    }

    // compass to objective
    if (state.mission && state.objective) {
      const dx = state.objective.x - state.playerX;
      const dz = state.objective.z - state.playerZ;
      const rel = Math.atan2(dx, dz) - state.heading;
      this.el.compassArrow.style.transform = `rotate(${rel * 180 / Math.PI}deg)`;
      this.el.compass.classList.remove('hidden');
    } else {
      this.el.compass.classList.add('hidden');
    }

    this.minimapTimer -= dt;
    if (this.minimapTimer <= 0) {
      this.minimapTimer = 1 / 20;
      this.drawMinimap(state);
    }
  }

  drawMinimap(state) {
    const ctx = this.mctx;
    const S = this.mapSize;
    const c = S / 2;
    const range = this.range;
    const zoom = S / (range * 2);
    const px = state.playerX;
    const pz = state.playerZ;

    ctx.save();
    ctx.clearRect(0, 0, S, S);
    ctx.beginPath();
    ctx.arc(c, c, c - 2, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = '#08202c';
    ctx.fillRect(0, 0, S, S);

    // static map in world units
    ctx.save();
    ctx.translate(c, c);
    ctx.scale(zoom, zoom);
    ctx.translate(-px, -pz);
    ctx.drawImage(this.staticMap, -270, -270, 540, 540);
    ctx.restore();

    const sx = (x) => c + (x - px) * zoom;
    const sy = (z) => c + (z - pz) * zoom;

    // mission marker
    if (state.objective) {
      const x = sx(state.objective.x), y = sy(state.objective.z);
      const pulse = 6 + Math.sin(performance.now() / 180) * 1.6;
      ctx.fillStyle = 'rgba(255,209,102,0.95)';
      ctx.beginPath();
      ctx.moveTo(x, y - pulse);
      ctx.lineTo(x + pulse, y);
      ctx.lineTo(x, y + pulse);
      ctx.lineTo(x - pulse, y);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    // cops
    for (const cop of state.cops) {
      if (!cop.active) continue;
      const x = sx(cop.pos.x), y = sy(cop.pos.z);
      if (x < 0 || y < 0 || x > S || y > S) continue;
      ctx.fillStyle = '#ff3b4e';
      ctx.beginPath(); ctx.arc(x, y, 4.4, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(255,80,90,0.35)';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(x, y, 8, 0, Math.PI * 2); ctx.stroke();
    }

    // pickups (cash only, nearby)
    for (const p of state.pickups) {
      if (!p.active || p.type !== 'cash') continue;
      const x = sx(p.pos.x), y = sy(p.pos.z);
      if (x < 0 || y < 0 || x > S || y > S) continue;
      ctx.fillStyle = 'rgba(125,255,110,0.85)';
      ctx.beginPath(); ctx.arc(x, y, 2.6, 0, Math.PI * 2); ctx.fill();
    }

    // player arrow
    ctx.save();
    ctx.translate(c, c);
    ctx.rotate(Math.PI - state.heading);
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -11);
    ctx.lineTo(8, 9);
    ctx.lineTo(0, 4);
    ctx.lineTo(-8, 9);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();

    // north marker
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.font = '700 18px Inter, Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('N', c, 24);
    ctx.restore();
  }
}

content.text:
Now main.js — game orchestration. This is the most complex.

Let me carefully plan code.

Imports:
```js
import * as THREE from '../vendor/three.module.js';
import { World, ROAD_COORDS, BOUNDARY } from './world.js';
import { Vehicle, Character, buildCarMesh, CAR_COLORS } from './vehicles.js';
import { TrafficSystem, PedestrianSystem, PoliceSystem } from './traffic.js';
import { FX } from './fx.js';
import { AudioEngine } from './audio.js';
import { UI } from './ui.js';
import { clamp, damp, dist2, money, canvasTexture, glowTexture, Rand } from './util.js';
```

Game class.

Renderer:
```js
const canvas = document.getElementById('scene');
this.renderer = new THREE.WebGLRenderer({canvas, antialias: !isMobile? true: true, powerPreference:'high-performance', stencil:false});
this.renderer.setSize(innerWidth, innerHeight);
this.renderer.setPixelRatio(Math.min(devicePixelRatio, isMobile?1.6:2));
this.renderer.shadowMap.enabled = true;
this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
this.renderer.toneMappingExposure = 1.05;
this.renderer.outputColorSpace = THREE.SRGBColorSpace;
```
Handle resize.

Scene camera.

World, fx, ui, audio.

Player vehicle spawn: x=0,z=12,heading=0.

Mission marker group: create.

Pickups.

State:
```js
this.state = {
  cash: 0, health: 100, wanted: 0, heatTimer: 0,
  jobs: 0, mission: null, missionTime: 0, missionDist: 0,
  objective: null, onFoot: false, started: false, paused: false, over: false,
  quality: isMobile? 'low' : 'high', muted: false, best: Number(localStorage...)||0,
  gear: 'N', kmh:0, boosting:false, drift:0, cops:[], pickups:[]
}
```
Note UI expects state.wanted, mission (object with name,index,total,time), missionTime, missionDist, objective, playerX/Z, heading, cops, pickups.

Input:
```js
this.keys = {};
this.touch = { left:false,right:false,gas:false,brake:false,hand:false,nitro:false };
```
Compute input each frame:
```js
const k = this.keys;
throttle = (k['w']||k['arrowup']||touch.gas?1:0) - (k['s']||k['arrowdown']||touch.brake?1:0)
steer = (k['a']||k['arrowleft']||touch.left?-1:0) + (k['d']||k['arrowright']||touch.right?1:0)
handbrake = k[' ']||touch.hand
nitro = k['shift']||touch.nitro
```
Careful: shift key event key === 'Shift'. Use k['shift'].

Keyboard listeners:
- keydown: set keys[e.key.toLowerCase()] = true; handle 'e' action once, 'p' pause, 'm' mute, 'r' respawn, 'c' camera? Use e.repeat guard.
- keyup.

Touch buttons: query all `[data-act]`. pointerdown -> set; pointerup/cancel/leave -> unset. Use `this.touch[act]=true`. For 'action' -> toggleVehicle() on pointerdown. For 'nitro' while on foot = run.

Also prevent scrolling: touch-action none on buttons.

Start:
```js
startBtn.addEventListener('click', () => this.startGame());
```
startGame:
- if already started return.
- audio.init(); audio.setMuted(state.muted)
- state.started=true; ui.setStarted(true);
- resetState(); startMission(0); camera snap behind car; toast.
- clock reset.

Attract mode loop:
- world.update(dt, time, vehicle.pos)
- traffic.update(dt, vehicle, time) — uses vehicle.pos; fine.
- peds.update(dt, vehicle, time)
- fx.update
- animate camera orbit: angle = time*0.08; radius 150; height 55; lookAt(0,10,0). Maybe show car near start.
- UI not updated.
- render.

Start camera should show city skyline; set camera at (-160, 60, 180) looking at (0,15,0) with slow drift. Use angle.

On start, camera.position set behind car immediately.

Update loop details:

```js
update(dt, time) {
  const st = this.state;
  if (st.over) { ... maybe still render world? freeze; }
  const input = this.getInput();
  st.onFoot ? this.updateOnFoot(dt, input, time) : this.updateDriving(dt, input, time);
  this.updateWanted(dt);
  this.updatePolice(dt, time);
  this.updateTraffic(dt, time);
  this.updatePeds(dt, time);
  this.updatePickups(dt);
  this.updateMission(dt);
  this.fx.update(dt, this.vehicle, time);
  this.world.update(dt, time, this.playerFocus());
  this.updateCamera(dt);
  this.updateStateForUI();
  this.ui.update(st, dt);
  this.audio.update({...});
  this.checkBusted...
}
```

Need to be careful about order: driving update may call enter etc.

Let me define `getInput()`:
```js
const t = this.touch, k = this.keys;
let throttle = (t.gas||k['w']||k['arrowup']?1:0) - (t.brake||k['s']||k['arrowdown']?1:0);
let steer = (t.left||k['a']||k['arrowleft']?-1:0) + (t.right||k['d']||k['arrowright']?1:0);
...
```
Note when on foot, brake button should move backward; throttle works.

`updateDriving`:
- vehicle.update(dt, input, world, time)
- if boosting and speed>10: fx.nitro at rear + maybe audio whoosh once.
- if driftFactor>0.15 and speed>6: fx.tireSmoke at rear wheels; skid marks each 0.05s (accumulate timer). Compute rear wheel positions:
```
const fwd = vehicle.forward(); const right = ...
rearX = pos.x - fwd.x*1.4; rearZ = pos.z - fwd.z*1.4; left/right offsets ±0.8
```
- if offroad (surface !== 'road') and speed>8: dust.
- collisions:
  - vehicle.collision -> impact: damage = clamp(impact*0.9, 0, 40); health -= damage; fx.impact at front; shake; audio.crash; ui flash; if impact>20 maybe explosion? no. Reset collision.
  - traffic collision loop; also cop collisions.
  - peds.
- Check near vehicle? no.
- If health <= 0 -> wrecked.
- If onFoot false, action button hidden (unless?).

Traffic collision:
```js
for (car of traffic.cars) {
  const dx = car.pos.x - v.pos.x, dz...
  const min = 3.2; if (d2 < min*min) {
    const d=..., nx=dx/d...
    // separate
    v.pos.x -= nx*(min-d)*0.7 ...
    car.pos.x += nx*(min-d)*0.3 ...
    const rel = vehicle.vel.x*nx + vehicle.vel.z*nz; // player moving toward car
    if (rel < -4) {
      damage...
      traffic.knock(car, -nx, -nz, Math.min(20, -rel*0.8));
      fx.impact(...); audio.crash
      // heat? no
    }
  }
}
```
Wait nx points from player to car. Player velocity toward car => v·n > 0. Let impact = v·n. If impact > 4: player damage = impact*0.4, knock car along n. Add small heat if car is police handled separately.

Police collision: similar, but damage cop hp = impact*4; if impact > 10 damage player 1-3; fx sparks; audio. Also wanted +? Ramming cops increases heat by 0.25 once per second.

Ped collision: if speed > 4 and dist < 2.4: hit, wanted += 0.7, fx.impact at ped, toast "CIVILIAN HIT +HEAT" (throttle). Slow car slightly: vehicle.vel *= 0.9. Also camera shake.

Pickups: loop, if active and dist < 3 (vehicle) or 1.5 (on foot):
- cash: value = p.value; state.cash += value; toast `+$${value}` cash; audio.cash; fx.pickup gold; p.active=false; hide; respawn timer 25-40.
- repair: health=min(100, health+45); toast "REPAIRED"; audio.pickup; cyan.
- nitro: nitro=100; toast "NITRO REFILLED"; audio.pickup; orange.
- deactivate: mesh.visible=false; p.respawn=rand(20,35). On respawn, move to new road point far from player, visible.

Mission update:
- if mission active: marker position = objective; animate; missionTime -= dt; missionDist = dist.
  - if missionDist < 8: checkpoint reached: index++; audio.beep; if index >= total -> completeMission else set new checkpoint, add 4s bonus? toast "CHECKPOINT".
  - if time <=0 -> failMission.
- marker visibility.
- if no mission and not over: missionCooldown -= dt; if <=0 startNextMission (index of mission). At game start we call startMission directly.
- Mission objects: {name, index, total, time, reward, checkpoints: [..], markerIndex}
  - Generate checkpoints: choose random road points with distance from current > 70 and from previous > 50.
  - Set objective = checkpoints[0].
  - time = 40 + total*20 maybe; mission.time for bar. state.missionTime counts down.
- complete: state.cash += reward; jobs++; toast `JOB COMPLETE +$reward`; audio.missionComplete; best update; save; mission=null; objective=null; marker hidden; cooldown 4s; start next with index+1 (missionCounter).
- fail: toast "JOB FAILED — TIME UP"; mission=null; cooldown 3s; start same index? use missionCounter unchanged so retry same difficulty.
- Mission names array ['WARM UP','CITY RUN','HOT CARGO','HEAT SEEKER','FIVE STAR RUN','NIGHT SHIFT','LAST DELIVERY'] then `JOB ${n}`.
- On start mission: wanted maybe set for later missions: if index>=2 -> addWanted(1) at start? MadOut missions would. Maybe not force; instead reward. Let's add for index>=3: wanted = max(wanted, 2) with toast "THE HEAT IS ON". Fine.
- Mission checkpoint positions should not be too far outside city.

Marker: group with ring & beam. Create:
```js
const ringGeo = new THREE.TorusGeometry(3.2,0.18,8,40); ringGeo.rotateX(PI/2);
ringMat = MeshBasicMaterial({color:0xffd166, transparent:true, opacity:.95, toneMapped:false});
beam = CylinderGeometry(1.0,3.4,30,16,1,true); beamMat = MeshBasicMaterial({color:0xffb84d, transparent:true, opacity:.10, side:DoubleSide, blending:Additive, depthWrite:false});
```
Add second ring? plus vertical arrow sprite? Add glow sprite. Marker group visible false.

Wanted update:
```js
if (st.wanted > 0) {
  st.heatTimer -= dt;
  if (st.heatTimer <= 0) st.wanted = Math.max(0, st.wanted - dt*0.12);
  if (st.wanted <= 0.02) st.wanted = 0;
}
```
Adding wanted: `addWanted(amount, reason)`:
- st.wanted = clamp(st.wanted + amount, 0, 5);
- heatTimer = 22;
- if crossed integer threshold -> toast `WANTED ${Math.ceil}` heat, audio.beep(520,...)
- stars pulse via UI.
- maybe spawn cops immediately (police.update handles).

Police update callbacks:
```js
police.update(dt, playerRef, wanted, time, {
  onShoot: (cop, dist) => { audio.gunshot(); fx.gunshot(cop.pos.x, 1.2, cop.pos.z, vehicle.pos.x, 1.0, vehicle.pos.z); if (wanted>=2) damage(2.2); shake; },
  onBusted: () => this.busted(),
  onCopWrecked: (cop) => { fx.explosion; audio.crash(2); cash?; wanted+=0.5; }
});
```
Player ref for police must be {pos, speed}. When on foot, use character. `playerRef = { pos: ..., speed: ... }`.

Cop distance for audio: min distance among active cops. Compute.

Busted check only when driving? Cops bust when near & slow. If on foot, same. Fine.

Damage function:
```js
damage(amount) {
  st.health -= amount;
  flash overlay class hit then remove after 60ms
  shake = max(shake, amount*0.05)
  if (st.health <= 0) this.wreck();
}
```
Wreck:
- explosion at vehicle pos; audio.crash; state.over=true; cash penalty 20%; ui.showOver('wrecked'); audio.suspend? keep; set started? HUD hidden? Show over screen, pause game updates (state.over).
- cops clear? Keep scene frozen.
Continue: reset after over:
  - state.over=false; health=100; wanted=0; heatTimer=0; vehicle reset to safe spot; mission=null; cooldown=2; ui.showOver(false); police.clear(); traffic.respawnFarFrom; character hidden; onFoot=false; camera snap; audio.resume.
  - penalty already applied.
  - hud show; start next mission after 2s.
- busted: similar with "busted", cash penalty 15%.

Pause handling:
- togglePause(): if !started or over return; paused=!paused; ui.showPause; audio suspend/resume; clock reset to avoid dt jump. Use renderer loop dt clamp anyway.
- On pause, render static scene.

Camera:
```js
updateCamera(dt) {
  if (onFoot) {
    const c=character; fwd=...; desired = c.pos - fwd*4.2 + (0,2.6,0); camera.position.lerp(desired, 1-exp(-8dt)); lookAt(c.pos + (0,1.2,0) + fwd*2); fov 62
  } else {
    const v=vehicle; speedRatio...
    const fwd = v.forward();
    const backDist = 7.4 + speedRatio*2.8 + (boosting?1.4:0);
    const height = 3.15 + speedRatio*0.5;
    const desired = v.pos - fwd*backDist + (0,height,0);
    camera.position.lerp(desired, 1-exp(-6.5dt));
    const look = v.pos + fwd*(5+speedRatio*7) + (0,1.15,0);
    // shake
    if (shake>0.01) add random offset, shake *= exp(-5dt)
    camera.lookAt(look);
    fov target 62 + speedRatio*10 + boost*5; lerp.
  }
  camera.updateProjectionMatrix if fov changed.
}
```
At start snap camera: set position directly.

Note camera lerp with desired behind car: when reversing, camera stays behind heading (car backs toward camera) — fine.

Shake variable on this.

Enter/exit:
```js
toggleVehicle() {
  if (state.onFoot) {
    // nearest own vehicle
    let best=null, bestD=4.8;
    const dOwn = dist(character, vehicle);
    if (dOwn < 4.8) best = 'own';
    else check traffic cars within 4.5 -> steal
    if (!best) return;
    if own: vehicle.reset? no, keep; just place vehicle at existing pos; character.hide(); onFoot=false;
    else steal...
  } else {
    if (Math.abs(vehicle.speed) > 12) { toast('SLOW DOWN TO GET OUT'); return; }
    state.onFoot = true;
    vehicle.vel.set(0,0,0); vehicle.speed=0;
    const side = right vector * 2.2; character.reset(vehicle.pos.x+side.x, vehicle.pos.z+side.z, vehicle.heading);
    character.mesh.group.visible = true;
    camera maybe.
  }
}
```
When exiting, vehicle should remain visible and not be updated; character appears beside. If char spawn inside building, resolve circle.

When on foot, updateOnFoot:
- character.update(dt, input, world)
- check nearest vehicle for action prompt: own vehicle distance < 5 or traffic < 5.
- UI action button visible if near; label ENTER/STEAL.
