+  const pos = [];
+  const uv = [];
+  const tri = (a, bb, c) => {
+    for (const p of [a, bb, c]) {
+      pos.push(p[0], p[1], p[2]);
+      uv.push(p[0] * 0.3 + 0.5, p[1] * 0.5);
+    }
+  };
+  // front (+z), rear (-z), right (+x), left (-x), top (+y)
+  tri(b[3], b[2], t[2]); tri(b[3], t[2], t[3]);
+  tri(b[1], b[0], t[0]); tri(b[1], t[0], t[1]);
+  tri(b[2], b[1], t[1]); tri(b[2], t[1], t[2]);
