input.newString:
@media (max-height: 520px) {
  .logo { font-size: clamp(56px, 13vh, 96px); }
  .blurb { display: none; }
  .feature-row { margin: 10px 0; }
  .start-foot { margin-top: 10px; }
  .modal { padding: 16px 22px; }
  .stats-grid { margin: 10px 0 12px; }
}

/* Landscape phones: keep every control inside the safe area and clear of
   the speedometer. The gauge moves under the top-left stats, while the
   nitro/drift/action buttons sit in a row above the pedals. */
@media (max-height: 520px) and (orientation: landscape) {
  body.touch #minimap { width: 128px; height: 128px; }
  body.touch #pauseBtn { top: calc(150px + var(--safe-t)); }
  body.touch #speedo {
    width: 92px;
    top: calc(104px + var(--safe-t));
    left: calc(14px + var(--safe-l));
    right: auto;
    bottom: auto;
    transform: none;
  }
  body.touch #speedVal { font-size: 27px; }
  body.touch .speed-unit { font-size: 7px; letter-spacing: 1.4px; }
  body.touch #gear { font-size: 8px; }
  body.touch #steerPad { left: calc(12px + var(--safe-l)); bottom: calc(14px + var(--safe-b)); gap: 8px; }
  body.touch #steerPad .steer { width: 58px; }
  body.touch #pedals { right: calc(12px + var(--safe-r)); bottom: calc(14px + var(--safe-b)); gap: 7px; }
  body.touch #pedals .pedal { width: 60px; }
  body.touch #pedals .brake { width: 50px; }
  body.touch #sideBtns {
    right: calc(12px + var(--safe-r));
    bottom: calc(158px + var(--safe-b));
    flex-direction: row;
    gap: 6px;
  }
  body.touch #sideBtns .small { width: 40px; font-size: 8px; }
  body.touch #modeHint { bottom: calc(104px + var(--safe-b)); }
}

